declare t record;b pg_catalog.pg_proc%rowtype;a pg_catalog.pg_proc%rowtype;
 d text;metadata jsonb;r record;
begin
 if current_user<>'postgres'
  or to_regprocedure('k2_private.start_guest_category_lot_context_v1(integer,uuid)') is not null then
  raise exception 'K2_GUEST_OPERATIONS_TARGET_INVALID';
 end if;
 -- Check every source/security contract before changing a function or table.
 for t in select * from jsonb_to_recordset('[{"signature":"k2_private.verify_guest_bff_request(text, bigint, uuid, text, text, text)","before":"808cec5d3a1be42e5b7e1ded833cc94f","after":"c3f66c3854464d3b0d03b26f445b432e","metadata":{"proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"verify_guest_bff_request","prorows":0,"pronargs":6,"proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":["p_action","p_timestamp","p_nonce","p_payload_text","p_ip_hash","p_signature"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":0},"body":"\ndeclare\n  v_secret bytea;\n  v_payload_hash text;\n  v_expected text;\n  v_message text;\nbegin\n  if p_timestamp is null or p_nonce is null or p_ip_hash is null or p_signature is null then\n    raise exception using errcode=''28000'', message=''K2_GUEST_SIGNATURE_INVALID'';\n  end if;\n  if p_action is null or p_action not in (''delivery_quote'',\n    ''order'',''pasabuy'',''coupon'',''guest_start'',''guest_read'',''guest_reply'',\n    ''account_claim'',''account_read'',''account_reply'',''wholesale_inquiry'',\n    ''account_settings_read'',''account_settings_write'',''account_notification_read''\n  ) then\n    raise exception using errcode=''22023'', message=''K2_GUEST_ACTION_INVALID'';\n  end if;\n  if p_payload_text is null or octet_length(convert_to(p_payload_text,''UTF8'')) > 24576 then\n    raise exception using errcode=''22023'', message=''K2_GUEST_PAYLOAD_INVALID'';\n  end if;\n  if p_ip_hash !~ ''^[0-9a-f]{64}$'' or p_signature !~ ''^[0-9a-f]{64}$'' then\n    raise exception using errcode=''28000'', message=''K2_GUEST_SIGNATURE_INVALID'';\n  end if;\n  if abs(extract(epoch from clock_timestamp())::bigint - p_timestamp) > 300 then\n    raise exception using errcode=''28000'', message=''K2_GUEST_SIGNATURE_EXPIRED'';\n  end if;\n  select request_secret into v_secret from k2_private.guest_bff_secrets where singleton=true;\n  if v_secret is null then\n    raise exception using errcode=''55000'', message=''K2_GUEST_BOUNDARY_NOT_CONFIGURED'';\n  end if;\n  v_payload_hash:=encode(extensions.digest(convert_to(p_payload_text,''UTF8''),''sha256''),''hex'');\n  v_message:=p_action||E''\\n''||p_timestamp::text||E''\\n''||p_nonce::text||E''\\n''||v_payload_hash||E''\\n''||p_ip_hash;\n  v_expected:=encode(extensions.hmac(convert_to(v_message,''UTF8''),v_secret,''sha256''),''hex'');\n  if extensions.digest(convert_to(v_expected,''UTF8''),''sha256'')\n     is distinct from extensions.digest(convert_to(p_signature,''UTF8''),''sha256'') then\n    raise exception using errcode=''28000'', message=''K2_GUEST_SIGNATURE_INVALID'';\n  end if;\n  delete from k2_private.guest_request_nonces where expires_at <= now();\n  insert into k2_private.guest_request_nonces(action,nonce,expires_at,verified_backend_pid,verified_transaction_id)\n  values(p_action,p_nonce,now()+interval ''10 minutes'',pg_catalog.pg_backend_pid(),pg_catalog.pg_current_xact_id()) on conflict do nothing;\n  return found;\nend;\n"},{"signature":"k2_private.start_category_lot_context_v1(integer)","before":"195f64f80687ee1a932d415ff4e48238","after":"fa779caddabc8215c824b1bcf6cfb3ad","metadata":{"proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"start_category_lot_context_v1","prorows":0,"pronargs":1,"proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":["p_maximum_depth"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":0},"body":"\ndeclare v_instant timestamptz;\nbegin\n if p_maximum_depth is null or p_maximum_depth<1 then\n  raise exception using errcode=''22023'',message=''K2_CATEGORY_CONTEXT_INPUT_INVALID'';\n end if;\n if auth.uid() is null or not public.is_staff() then\n  raise exception using errcode=''42501'',message=''K2_STAFF_REQUIRED'';\n end if;\n if coalesce(auth.jwt()->>''aal'','''')<>''aal2'' then\n  raise exception using errcode=''42501'',message=''K2_AAL2_REQUIRED'';\n end if;\n -- Verify an existing boundary; never acquire a late policy lock here.\n if not exists(select 1 from pg_catalog.pg_locks l where l.pid=pg_catalog.pg_backend_pid()\n  and l.locktype=''advisory'' and l.classid=1261585232::oid and l.objid=1347374169::oid\n  and l.objsubid=2 and l.granted and l.mode in (''ShareLock'',''ExclusiveLock'')) then\n  raise exception using errcode=''55000'',message=''K2_CATEGORY_CONTEXT_ENTRY_REQUIRED'';\n end if;\n if exists(select 1 from k2_private.category_lot_command_context\n  where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n  raise exception using errcode=''55000'',message=''K2_CATEGORY_CONTEXT_ALREADY_SET'';\n end if;\n v_instant:=pg_catalog.clock_timestamp();\n insert into k2_private.category_lot_command_context\n (backend_pid,transaction_id,actor_id,maximum_depth,evaluation_instant,authority_kind,guest_nonce)\n values(pg_catalog.pg_backend_pid(),pg_catalog.pg_current_xact_id(),auth.uid(),p_maximum_depth,v_instant,''staff'',null);\n return v_instant;\nend "},{"signature":"k2_private.current_category_lot_context_v1()","before":"8354367b47bf437c8f0e7cda37417eab","after":"0ace340532be2d89ba8b2230e37f245f","metadata":{"proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"current_category_lot_context_v1","prorows":0,"pronargs":0,"proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":null,"proisstrict":false,"proparallel":"u","provolatile":"s","proleakproof":false,"pronargdefaults":0},"body":"\ndeclare v_context k2_private.category_lot_command_context;\nbegin\n select * into v_context from k2_private.category_lot_command_context\n  where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id();\n if not found then raise exception using errcode=''55000'',message=''K2_CATEGORY_CONTEXT_REQUIRED'';end if;\n if v_context.actor_id is distinct from auth.uid() then\n  raise exception using errcode=''42501'',message=''K2_CATEGORY_CONTEXT_ACTOR_MISMATCH'';\n end if;\n if v_context.authority_kind=''guest'' then\n  if not exists(select 1 from k2_private.guest_request_nonces n\n  where n.action=''order'' and n.nonce=v_context.guest_nonce\n   and n.verified_backend_pid=pg_catalog.pg_backend_pid()\n   and n.verified_transaction_id=pg_catalog.pg_current_xact_id()\n   and n.expires_at>pg_catalog.clock_timestamp()) then\n   raise exception using errcode=''42501'',message=''K2_GUEST_CONTEXT_PROOF_REQUIRED'';\n  end if;\n elsif v_context.authority_kind=''staff'' then\n  if not public.is_staff() then raise exception using errcode=''42501'',message=''K2_STAFF_REQUIRED'';end if;\n  if coalesce(auth.jwt()->>''aal'','''')<>''aal2'' then raise exception using errcode=''42501'',message=''K2_AAL2_REQUIRED'';end if;\n else\n  raise exception using errcode=''42501'',message=''K2_CATEGORY_CONTEXT_AUTHORITY_INVALID'';\n end if;\n return v_context;\nend "},{"signature":"k2_private.clear_category_lot_context_v1()","before":"2eeb3aa429998a8cef36782ef6b83b71","after":"d4bae070672f12c882b0d729f0fb9c4f","metadata":{"proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"clear_category_lot_context_v1","prorows":0,"pronargs":0,"proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":null,"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":0},"body":"\nbegin\n perform k2_private.current_category_lot_context_v1();\n delete from k2_private.category_lot_command_context where backend_pid=pg_catalog.pg_backend_pid()\n  and transaction_id=pg_catalog.pg_current_xact_id() and actor_id is not distinct from auth.uid();\nend "},{"signature":"public.submit_guest_order_v1(bigint, uuid, text, text, text, text)","before":"c58cdccacdf786598c891ae191be303b","after":"e4b5a7997a2e7d47a7be3e6d7fbdef79","metadata":{"proacl":["postgres=X/postgres","anon=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"submit_guest_order_v1","prorows":1000,"pronargs":6,"proconfig":["search_path=\"\""],"proretset":true,"prosecdef":true,"proargmodes":["i","i","i","i","i","i","t","t","t","t","t","t","t","t","t","t","t","t"],"proargnames":["p_timestamp","p_nonce","p_payload_text","p_ip_hash","p_signature","p_guest_grant_hash","ok","error_code","retry_after_seconds","public_reference","status","subtotal","discount_amount","total_amount","shipping_quote_status","delivery_status","created_at","guest_grant_token"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":1},"body":"\ndeclare\n  v_payload jsonb;\n  v_order public.order_requests;\n  v_identity record;\n  v_conversation_id uuid;\n  v_message_id uuid;\n  v_ip bytea;\n  v_contact bytea;\n  v_rate record;\n  v_fingerprint bytea;\n  v_existing_hash bytea;\n  v_shipping_num numeric;\n  v_depth integer;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not k2_private.verify_guest_bff_request(''order'', p_timestamp, p_nonce, p_payload_text, p_ip_hash, p_signature) then\n    return query select false, ''REQUEST_REPLAYED'', 0, null::text, null::text, null::numeric,\n      null::numeric, null::numeric, null::text, null::text, null::timestamptz, null::text;\n    return;\n  end if;\n  v_payload := p_payload_text::jsonb;\n  v_ip := decode(p_ip_hash, ''hex'');\n  v_contact := k2_private.contact_hash(v_payload);\n  v_fingerprint := extensions.digest(convert_to(p_payload_text, ''UTF8''), ''sha256'');\n  if p_guest_grant_hash ~ ''^[0-9a-f]{64}$'' then v_existing_hash := decode(p_guest_grant_hash, ''hex''); end if;\n\n  select * into v_rate from k2_private.consume_guest_rate(''order'',''ip'',v_ip,900,5);\n  if not v_rate.allowed then\n    return query select false, ''RATE_LIMITED'', v_rate.retry_after_seconds, null::text, null::text,\n      null::numeric, null::numeric, null::numeric, null::text, null::text, null::timestamptz, null::text;\n    return;\n  end if;\n  select * into v_rate from k2_private.consume_guest_rate(''order'',''contact'',v_contact,3600,3);\n  if not v_rate.allowed then\n    return query select false, ''RATE_LIMITED'', v_rate.retry_after_seconds, null::text, null::text,\n      null::numeric, null::numeric, null::numeric, null::text, null::text, null::timestamptz, null::text;\n    return;\n  end if;\n\n  -- Match the canonical writer: serialize the key before inventory/FK locks.\n  perform pg_advisory_xact_lock(hashtextextended(''k2.website-order:''||trim(v_payload->>''idempotencyKey''),0));\n  select * into v_order from public.order_requests\n  where idempotency_key = v_payload->>''idempotencyKey'';\n  if found then\n    if v_order.request_fingerprint is distinct from v_fingerprint then\n      return query select false, ''IDEMPOTENCY_CONFLICT'', 0, null::text, null::text,\n        null::numeric, null::numeric, null::numeric, null::text, null::text, null::timestamptz, null::text;\n    else\n      return query select true, null::text, 0, v_order.public_reference, v_order.status,\n        v_order.subtotal, v_order.discount_amount, v_order.total_amount,\n        v_order.shipping_quote_status, v_order.delivery_status, v_order.created_at, null::text;\n    end if;\n    return;\n  end if;\n\n  -- Saved receipt/conflict above skips fresh policy configuration and stock.\n  perform 1 from public.coupons\n   where code=upper(trim(v_payload->>''couponCode'')) for update;\n  perform k2_private.require_website_order_items(v_payload->''items'');\n  perform 1 from public.product_batches b\n   where b.sku in(select item->>''sku'' from jsonb_array_elements(v_payload->''items'') item)\n   order by b.sku,b.id for update;\n  if exists(select 1 from public.inventory_balances b\n   where b.location_code=''MANILA_MAIN''\n    and b.sku in(select item->>''sku'' from jsonb_array_elements(v_payload->''items'') item)\n    and (b.on_hand<0 or b.reserved<0 or b.reserved>b.on_hand)) then\n   raise exception using errcode=''23514'',message=''K2_RESERVATION_BALANCE_MISMATCH'';\n  end if;\n  select maximum_depth into v_depth from k2_private.category_policy_command_config where singleton;\n  if v_depth is null or v_depth<1 then\n   raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n  end if;\n  perform k2_private.start_guest_category_lot_context_v1(v_depth,p_nonce);\n  select * into v_identity from k2_private.resolve_guest_identity(\n    v_payload, ''website_guest'', v_existing_hash\n  );\n  v_order := public.submit_order_request_v2(\n    v_payload->>''customerName'', nullif(v_payload->>''email'',''''), nullif(v_payload->>''phone'',''''),\n    v_payload->>''address'', v_payload->>''fulfillmentMethod'', nullif(v_payload->>''note'',''''),\n    v_payload->''items'', v_payload->>''idempotencyKey'', nullif(v_payload->>''couponCode'','''')\n  );\n\n  -- Apply upfront delivery quotation if provided by checkout\n  if (v_payload->>''shippingAmount'') is not null then\n    begin\n      v_shipping_num := (v_payload->>''shippingAmount'')::numeric;\n      if v_shipping_num >= 0 and v_shipping_num <= 100000 then\n        update public.order_requests as o\n        set shipping_amount = v_shipping_num,\n            shipping_quote_status = coalesce(nullif(v_payload->>''shippingQuoteStatus'',''''), ''customer_confirmed''),\n            total_amount = o.subtotal - o.discount_amount + v_shipping_num,\n            customer_delivery_confirmed_at = now(),\n            updated_at = now()\n        where o.id = v_order.id\n        returning o.* into v_order;\n      end if;\n    exception when others then\n      -- Fall back cleanly to unpriced order request on invalid numeric\n      null;\n    end;\n  end if;\n\n  update public.order_requests set customer_id=v_identity.customer_id,\n    request_fingerprint=v_fingerprint where id=v_order.id returning * into v_order;\n\n  insert into public.conversations(\n    customer_id, customer_name, customer_email, customer_phone, platform, source_kind, source_id\n  ) values (\n    v_identity.customer_id, v_order.customer_name, v_order.customer_email, v_order.customer_phone,\n    ''Website'', ''order_request'', v_order.id\n  )\n  on conflict (source_kind, source_id)\n    where source_kind is not null and source_id is not null\n  do update set\n    customer_id=excluded.customer_id,\n    customer_name=excluded.customer_name,\n    customer_email=excluded.customer_email,\n    customer_phone=excluded.customer_phone,\n    updated_at=now()\n  returning id into v_conversation_id;\n\n  insert into public.messages(\n    conversation_id, sender_type, content, is_draft, delivery_status, provider_event_key, direction\n  )\n  select v_conversation_id, ''Customer'',\n    ''Order '' || v_order.public_reference || '' received through the website. ''\n      || ''Delivery option: '' || coalesce(v_order.fulfillment_method, ''Standard'') || '' (₱'' || v_order.shipping_amount::text || ''). ''\n      || ''Total: ₱'' || v_order.total_amount::text || ''. Staff verify Manila stock and contact with payment details.'',\n    false, ''received'', ''guest-order-seed:'' || v_order.id::text, ''inbound''\n  where not exists (\n    select 1 from public.messages\n    where conversation_id = v_conversation_id\n      and (provider_event_key in (''guest-order-seed:'' || v_order.id::text, ''order_seed_'' || v_order.id::text)\n        or external_message_id in (''guest-order-seed:'' || v_order.id::text, ''order_seed_'' || v_order.id::text))\n  )\n  returning id into v_message_id;\n\n  insert into public.conversation_events(\n    conversation_id, event_type, reason, metadata\n  )\n  select v_conversation_id, ''inbound_message'',\n    ''Seeded customer conversation from order submission '' || v_order.public_reference,\n    jsonb_build_object(''order_id'',v_order.id,''public_reference'',v_order.public_reference,''source_kind'',''order_request'')\n  where v_message_id is not null;\n\n  if v_message_id is not null then\n    update public.conversations\n    set unread_count=1,last_inbound_at=now(),response_due_at=now()+interval ''4 hours'',\n      last_message_at=now(),updated_at=now()\n    where id=v_conversation_id;\n  end if;\n\n  insert into public.guest_access_grant_scopes(grant_id,scope_kind,scope_id,permissions)\n  values\n    (v_identity.grant_id,''order_request'',v_order.id,array[''read'']::text[]),\n    (v_identity.grant_id,''conversation'',v_conversation_id,array[''read'',''reply'']::text[])\n  on conflict do nothing;\n\n  perform k2_private.clear_category_lot_context_v1();\n  return query select true, null::text, 0, v_order.public_reference, v_order.status,\n    v_order.subtotal, v_order.discount_amount, v_order.total_amount,\n    v_order.shipping_quote_status, v_order.delivery_status, v_order.created_at,\n    v_identity.raw_grant_token;\nend;\n"},{"signature":"public.confirm_order_request(uuid, text)","before":"91ac2250115d77799fe300cc2e587743","after":"36967b6d0c2f85f25a02f5c351df22a2","metadata":{"proacl":null,"probin":null,"procost":100,"prokind":"f","proname":"confirm_order_request","prorows":0,"pronargs":2,"proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":["p_order_request_id","p_reason"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":1},"body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_line public.order_request_items;\n  v_coupon public.coupons;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() then raise exception ''Staff access required''; end if;\n  select * into v_order from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n  if v_order.status = ''confirmed'' then return v_order; end if;\n  if v_order.status <> ''submitted'' then raise exception ''Only submitted requests can be confirmed''; end if;\n\n  perform 1 from public.coupons where id=v_order.coupon_id for update;\n  insert into public.inventory_balances(sku,location_code,on_hand,reserved)\n  select p.sku,''MANILA_MAIN'',coalesce(sum(b.quantity),0)::integer,coalesce(sum(b.reserved_quantity),0)::integer\n  from public.products p left join public.product_batches b on b.sku=p.sku\n  where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id)\n  group by p.sku order by p.sku on conflict(sku,location_code) do nothing;\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  if v_order.coupon_id is not null then\n    select * into v_coupon from public.coupons where id = v_order.coupon_id for update;\n    if not found or not v_coupon.is_active or v_coupon.archived_at is not null\n       or v_coupon.starts_at > v_k2_instant or (v_coupon.ends_at is not null and v_coupon.ends_at <= v_k2_instant)\n       or (v_coupon.max_redemptions is not null and v_coupon.redemption_count >= v_coupon.max_redemptions) then\n      raise exception ''The coupon is no longer available'';\n    end if;\n    update public.coupons set redemption_count = redemption_count + 1 where id = v_coupon.id;\n    insert into public.coupon_redemptions (coupon_id, order_request_id, discount_amount)\n    values (v_coupon.id, v_order.id, v_order.discount_amount);\n  end if;\n\n  perform public.reserve_order_request_lots_v1(v_order.id, p_reason);\n\n  for v_line in select * from public.order_request_items where order_request_id = v_order.id order by created_at\n  loop\n    insert into public.orders (\n      sku, quantity, channel_source, fulfillment_method, order_status,\n      payment_status, customer_name, customer_email, total_amount, order_request_id\n    ) values (\n      v_line.sku, v_line.quantity,\n      case v_order.channel_source\n        when ''shopee'' then ''shopee''::channel_type\n        when ''lazada'' then ''lazada''::channel_type\n        when ''tiktok'' then ''tiktok''::channel_type\n        else ''website_retail''::channel_type end,\n      v_order.fulfillment_method, ''Pending''::order_status_enum, ''Unpaid''::payment_status_enum,\n      v_order.customer_name, v_order.customer_email, v_line.line_total, v_order.id\n    );\n  end loop;\n\n  update public.order_requests\n  set status = ''confirmed'', confirmed_by = auth.uid(), confirmed_at = v_k2_instant,\n      delivery_status = case when shipping_quote_status in (''platform_charged'', ''customer_confirmed'', ''waived'') then ''ready_to_pack'' else delivery_status end,\n      updated_at = v_k2_instant\n  where id = v_order.id returning * into v_order;\n\n  -- Owned stock leaves the sellable pool here, once. The early return above\n  -- keeps a replayed confirmation from deducting again, and the helper\n  -- itself skips already-committed allocations, so both guards agree.\n  perform public.commit_order_request_stock_v1(v_order.id, ''confirmation'', p_reason);\n\n  insert into public.order_request_events (order_request_id, from_status, to_status, reason, actor_id, created_at)\n  values (v_order.id, ''submitted'', ''confirmed'', p_reason, auth.uid(), v_k2_instant);\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return v_order;\nend;\n"},{"signature":"public.cancel_order_request(uuid, text)","before":"cc96642602da36b41b12ea223b32d1ae","after":"1bf23bd7d10069bc7add637d6a499a5b","metadata":{"proacl":null,"probin":null,"procost":100,"prokind":"f","proname":"cancel_order_request","prorows":0,"pronargs":2,"proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":["p_order_request_id","p_reason"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":0},"body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_res public.inventory_reservations;\n  v_summary record;\n\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() then raise exception ''Staff access required''; end if;\n  if nullif(trim(coalesce(p_reason, '''')), '''') is null then raise exception ''Cancellation reason is required''; end if;\n  select * into v_order from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n  if v_order.status = ''cancelled'' then return v_order; end if;\n  if v_order.status not in (''submitted'', ''confirmed'') then raise exception ''This order request cannot be cancelled''; end if;\n\n  perform 1 from public.coupons where id=v_order.coupon_id for update;\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  -- Submitted purchases hold stock too. Summarize only currently active lots,\n  -- then acquire balance before batch locks in SKU order, as reservation does.\n  for v_summary in select sku, sum(quantity)::integer quantity\n    from public.inventory_reservations\n    where order_request_id = v_order.id and status = ''active''\n    group by sku order by sku\n  loop\n    update public.inventory_balances set reserved = reserved - v_summary.quantity, updated_at = v_k2_instant\n    where sku = v_summary.sku and location_code = ''MANILA_MAIN'' and reserved >= v_summary.quantity;\n    if not found then raise exception ''Inventory reservation mismatch for %'', v_summary.sku; end if;\n\n    for v_res in select * from public.inventory_reservations\n      where order_request_id = v_order.id and status = ''active'' and sku = v_summary.sku\n      order by batch_id, id for update\n    loop\n      update public.product_batches set reserved_quantity = reserved_quantity - v_res.quantity, updated_at = v_k2_instant\n      where id = v_res.batch_id and reserved_quantity >= v_res.quantity;\n      if not found then raise exception ''Lot reservation mismatch for %'', v_res.sku; end if;\n      update public.inventory_reservations\n      set status = ''released'', released_at = v_k2_instant, release_cause = ''cancelled'', updated_at = v_k2_instant\n      where id = v_res.id;\n    end loop;\n\n    perform set_config(''k2.allow_stock_write'', ''on'', true);\n    update public.products set stock_available = (\n      select coalesce(sum(b.quantity - b.reserved_quantity), 0)::integer from public.product_batches b\n      where b.sku = v_summary.sku and b.inventory_status = ''available''\n        and k2_private.lot_is_eligible_v1(b)\n    ) where sku = v_summary.sku;\n    insert into public.inventory_events (sku, location_code, event_type, quantity, reference_type, reference_id, reason, actor_id, created_at)\n    values (v_summary.sku, ''MANILA_MAIN'', ''reservation_released'', v_summary.quantity, ''order_request'', v_order.id, p_reason, auth.uid(), v_k2_instant);\n  end loop;\n\n  update public.orders set order_status = ''Cancelled''::order_status_enum\n  where order_request_id = v_order.id and order_status::text <> ''Shipped'';\n\n  if v_order.coupon_id is not null then\n    update public.coupon_redemptions set status = ''released'', updated_at = v_k2_instant\n    where order_request_id = v_order.id and status = ''reserved'';\n    if found then update public.coupons set redemption_count = greatest(redemption_count - 1, 0) where id = v_order.coupon_id; end if;\n  end if;\n  update public.order_requests\n  set status = ''cancelled'', delivery_status = ''cancelled'', exception_status = ''resolved'',\n      exception_note = trim(p_reason), cancelled_at = v_k2_instant, updated_at = v_k2_instant\n  where id = v_order.id returning * into v_order;\n  insert into public.order_request_events (order_request_id, from_status, to_status, reason, actor_id, created_at)\n  values (v_order.id, case when v_order.confirmed_at is null then ''submitted'' else ''confirmed'' end, ''cancelled'', p_reason, auth.uid(), v_k2_instant);\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return v_order;\nend;\n"},{"signature":"public.set_order_request_payment_status(uuid, text, text, jsonb)","before":"c124b51c31ad80cd558bf686282c3f82","after":"c7be6e145bec58a0a94df70a5980868b","metadata":{"proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"set_order_request_payment_status","prorows":0,"pronargs":4,"proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":["p_order_request_id","p_to_status","p_evidence_note","p_payment_evidence"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":0},"body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_from text;\n  v_submitter uuid;\n  v_structured_evidence jsonb := ''{}''::jsonb;\n  v_method text;\n  v_amount numeric;\n  v_currency text;\n  v_payer_name text;\n  v_payment_reference text;\n  v_proof_asset_ref text;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() or auth.uid() is null\n     or coalesce(auth.jwt()->>''aal'','''') <> ''aal2'' then\n    raise exception using errcode=''42501'', message=''K2_ADMIN_AAL2_REQUIRED'';\n  end if;\n\n  select * into v_order from public.order_requests where id=p_order_request_id for update;\n  if not found then raise exception using errcode=''23514'', message=''K2_PAYMENT_ORDER_INELIGIBLE''; end if;\n  v_from := v_order.payment_status;\n  if p_to_status = v_from then return v_order; end if;\n\n  if not coalesce((\n    (v_from=''not_requested'' and p_to_status=''awaiting_instructions'') or\n    (v_from=''awaiting_instructions'' and p_to_status in (''evidence_submitted'',''failed'')) or\n    (v_from=''evidence_submitted'' and p_to_status in (''verified'',''failed'')) or\n    (v_from=''failed'' and p_to_status=''evidence_submitted'') or\n    (v_from=''verified'' and p_to_status=''refunded'')\n  ), false) then\n    raise exception using errcode=''23514'', message=''K2_PAYMENT_TRANSITION_INVALID'';\n  end if;\n\n  if length(trim(coalesce(p_evidence_note,''''))) > 1000 or\n     (p_to_status not in (''awaiting_instructions'', ''evidence_submitted'') and nullif(trim(coalesce(p_evidence_note,'''')),'''') is null) then\n    raise exception using errcode=''23514'', message=''K2_PAYMENT_EVIDENCE_REQUIRED'';\n  end if;\n\n  -- Refund reconciliation remains available for a verified cancelled/fulfilled order;\n  -- all new attempts and collection/verification require an open order.\n  if p_to_status <> ''refunded'' and v_order.status not in (''submitted'',''confirmed'') then\n    raise exception using errcode=''23514'', message=''K2_PAYMENT_ORDER_INELIGIBLE'';\n  end if;\n\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  if p_to_status in (''evidence_submitted'',''verified'') then\n    -- K2_PAYMENT_BALANCE_INTEGRITY_V1\n    perform 1 from public.order_request_items where order_request_id=v_order.id order by id for update;\n    perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN''\n      and b.sku in (select sku from public.order_request_items where order_request_id=v_order.id)\n      order by b.sku for update;\n    perform 1 from public.inventory_reservations where order_request_id=v_order.id order by sku,batch_id,id for update;\n    perform 1 from public.product_batches b where b.id in (\n      select batch_id from public.inventory_reservations where order_request_id=v_order.id and status=''active''\n    ) order by b.sku,b.id for update;\n\n    if exists (\n      select 1 from public.order_request_items i\n      left join public.inventory_balances b on b.sku=i.sku and b.location_code=''MANILA_MAIN''\n      where i.order_request_id=v_order.id and (\n        b.sku is null or b.reserved is null or b.on_hand is null\n        or b.reserved<0 or b.reserved>b.on_hand\n        or b.reserved<(select coalesce(sum(r.quantity),0) from public.inventory_reservations r\n          where r.order_request_id=v_order.id and r.sku=i.sku and r.status=''active'')\n      )\n    ) then\n      raise exception using errcode=''23514'', message=''K2_PAYMENT_STOCK_INELIGIBLE'';\n    end if;\n\n    if not exists(select 1 from public.order_request_items where order_request_id=v_order.id)\n      or exists (\n        select 1 from public.inventory_reservations r\n        left join public.order_request_items i on i.id=r.order_request_item_id and i.order_request_id=v_order.id and i.sku=r.sku\n        left join public.product_batches b on b.id=r.batch_id and b.sku=r.sku\n        where r.order_request_id=v_order.id and r.status=''active''\n          and (i.id is null or b.id is null or r.quantity<=0\n            or ((r.committed_at is not null or r.committed_by is not null or r.commit_cause is not null)\n              and not coalesce(r.committed_at is not null and r.committed_by is not null\n                and r.commit_cause in (''confirmation'',''payment_verification''),false))\n            or (r.committed_at is null and (r.expires_at is null or r.expires_at<=v_k2_instant))\n            or b.reserved_quantity < (select sum(r2.quantity) from public.inventory_reservations r2 where r2.batch_id=b.id and r2.status=''active''))\n      )\n      or exists (\n        select 1 from public.order_request_items i where i.order_request_id=v_order.id\n        and i.quantity <> coalesce((\n          select sum(r.quantity) from public.inventory_reservations r\n          join public.product_batches b on b.id=r.batch_id and b.sku=r.sku\n          where r.order_request_id=v_order.id and r.order_request_item_id=i.id and r.sku=i.sku\n            and r.status=''active'' and r.quantity>0\n            and (r.committed_at is not null or r.expires_at>v_k2_instant)\n            and b.inventory_status=''available''\n            and b.quantity>=b.reserved_quantity and b.reserved_quantity>=r.quantity\n            and k2_private.lot_is_eligible_v1(b)\n        ),0)\n      ) then\n      raise exception using errcode=''23514'', message=''K2_PAYMENT_STOCK_INELIGIBLE'';\n    end if;\n  end if;\n\n  if p_to_status = ''evidence_submitted'' then\n    if p_payment_evidence is not null and p_payment_evidence <> ''{}''::jsonb then\n      v_method := p_payment_evidence->>''method'';\n      if v_method is null or v_method not in (''gcash'', ''bank_transfer'', ''maya'', ''cash'', ''other'') then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_METHOD_INVALID'';\n      end if;\n\n      begin\n        v_amount := (p_payment_evidence->>''amount'')::numeric;\n      exception when others then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_AMOUNT_INVALID'';\n      end;\n      if v_amount is null or v_amount <= 0 or v_amount > 10000000 then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_AMOUNT_INVALID'';\n      end if;\n\n      v_currency := coalesce(p_payment_evidence->>''currency'', ''PHP'');\n      if v_currency <> ''PHP'' then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_CURRENCY_INVALID'';\n      end if;\n\n      v_payer_name := trim(coalesce(p_payment_evidence->>''payer_name'', ''''));\n      if length(v_payer_name) not between 1 and 140 then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_PAYER_INVALID'';\n      end if;\n\n      v_payment_reference := trim(coalesce(p_payment_evidence->>''payment_reference'', ''''));\n      if length(v_payment_reference) not between 1 and 100 then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_REFERENCE_INVALID'';\n      end if;\n\n      v_proof_asset_ref := trim(coalesce(p_payment_evidence->>''proof_asset_ref'', ''''));\n      if length(v_proof_asset_ref) > 500 then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_PROOF_INVALID'';\n      end if;\n\n      v_structured_evidence := jsonb_build_object(\n        ''method'', v_method,\n        ''amount'', v_amount,\n        ''currency'', v_currency,\n        ''payer_name'', v_payer_name,\n        ''payment_reference'', v_payment_reference,\n        ''proof_asset_ref'', nullif(v_proof_asset_ref, ''''),\n        ''submitted_at'', v_k2_instant,\n        ''submitted_by'', auth.uid()\n      );\n    else\n      -- If structured fields omitted, note must be present\n      if nullif(trim(coalesce(p_evidence_note, '''')), '''') is null then\n        raise exception using errcode=''23514'', message=''K2_PAYMENT_EVIDENCE_REQUIRED'';\n      end if;\n      v_structured_evidence := jsonb_build_object(\n        ''legacy_note'', trim(p_evidence_note),\n        ''submitted_at'', v_k2_instant,\n        ''submitted_by'', auth.uid()\n      );\n    end if;\n\n    update public.order_requests\n    set payment_status = p_to_status,\n        payment_evidence = v_structured_evidence,\n        updated_at = v_k2_instant\n    where id = v_order.id\n    returning * into v_order;\n\n    insert into public.order_request_events(\n      order_request_id, from_status, to_status, reason, actor_id, metadata, created_at\n    )\n    values(\n      v_order.id, v_order.status, v_order.status, trim(coalesce(p_evidence_note, v_payment_reference, '''')),\n      auth.uid(),\n      jsonb_build_object(\n        ''event'', ''payment_status_changed'',\n        ''from'', v_from,\n        ''to'', p_to_status,\n        ''corrected_attempt'', v_from = ''failed'',\n        ''payment_evidence'', v_structured_evidence\n      ),\n      v_k2_instant\n    );\n\n  elsif p_to_status = ''verified'' then\n    select actor_id into v_submitter from public.order_request_events\n      where order_request_id = v_order.id and metadata->>''event'' = ''payment_status_changed''\n        and metadata->>''to'' = ''evidence_submitted''\n      order by created_at desc, id desc limit 1;\n\n    if v_submitter is null or v_submitter = auth.uid() then\n      raise exception using errcode=''42501'', message=''K2_PAYMENT_INDEPENDENT_REVIEW_REQUIRED'';\n    end if;\n\n    -- K2_STRUCTURED_PAYMENT_STOCK_COMMITMENT_V1: after eligibility and distinct review.\n    perform public.commit_order_request_stock_v1(v_order.id,''payment_verification'',p_evidence_note);\n    v_structured_evidence := coalesce(v_order.payment_evidence, ''{}''::jsonb) || jsonb_build_object(\n      ''verified_at'', v_k2_instant,\n      ''verified_by'', auth.uid(),\n      ''verification_note'', trim(p_evidence_note)\n    );\n\n    update public.order_requests\n    set payment_status = p_to_status,\n        payment_evidence = v_structured_evidence,\n        updated_at = v_k2_instant\n    where id = v_order.id\n    returning * into v_order;\n\n    insert into public.order_request_events(\n      order_request_id, from_status, to_status, reason, actor_id, metadata, created_at\n    )\n    values(\n      v_order.id, v_order.status, v_order.status, trim(p_evidence_note),\n      auth.uid(),\n      jsonb_build_object(\n        ''event'', ''payment_status_changed'',\n        ''from'', v_from,\n        ''to'', p_to_status,\n        ''corrected_attempt'', false,\n        ''verification'', jsonb_build_object(\n          ''verified_by'', auth.uid(),\n          ''verified_at'', v_k2_instant,\n          ''note'', trim(p_evidence_note)\n        )\n      ),\n      v_k2_instant\n    );\n\n  else\n    update public.order_requests\n    set payment_status = p_to_status,\n        updated_at = v_k2_instant\n    where id = v_order.id\n    returning * into v_order;\n\n    insert into public.order_request_events(\n      order_request_id, from_status, to_status, reason, actor_id, metadata, created_at\n    )\n    values(\n      v_order.id, v_order.status, v_order.status, trim(coalesce(p_evidence_note, '''')),\n      auth.uid(),\n      jsonb_build_object(\n        ''event'', ''payment_status_changed'',\n        ''from'', v_from,\n        ''to'', p_to_status,\n        ''corrected_attempt'', v_from = ''failed''\n      ),\n      v_k2_instant\n    );\n  end if;\n\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return v_order;\nend;\n"},{"signature":"public.record_packing_scan_exact_v1(uuid, text, uuid, boolean)","before":"84012276355c2d45903c6aec553b6f88","after":"a65edce5045b4b420c1d0068362838bc","metadata":{"proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"record_packing_scan_exact_v1","prorows":0,"pronargs":4,"proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":["p_order_request_id","p_scanned_code","p_reservation_id","p_lot_confirmed"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":0},"body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n v_order public.order_requests; v_res public.inventory_reservations;\n v_line public.order_request_items; v_batch public.product_batches; v_scan integer; v_total integer; v_complete boolean;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n if not public.is_staff() or auth.uid() is null then raise exception ''Staff access required'' using errcode=''42501''; end if;\n if p_lot_confirmed is distinct from true then raise exception ''K2_PACKING_LOT_CONFIRMATION_REQUIRED'' using errcode=''23514''; end if;\n select * into v_order from public.order_requests where id=p_order_request_id for update;\n if not found or v_order.status is distinct from ''confirmed'' then raise exception ''K2_PACKING_ALLOCATION_INVALID'' using errcode=''23514''; end if;\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n select * into v_res from public.inventory_reservations where id=p_reservation_id and order_request_id=v_order.id for update;\n if not found or v_res.status is distinct from ''active'' or v_res.packed_quantity is null\n   or v_res.quantity is null or v_res.quantity<=0 or v_res.packed_quantity<0 or v_res.packed_quantity>=v_res.quantity then\n  raise exception ''K2_PACKING_ALLOCATION_INVALID'' using errcode=''23514''; end if;\n select i.* into v_line from public.order_request_items i join public.products p on p.sku=i.sku\n  where i.id=v_res.order_request_item_id and i.order_request_id=v_order.id and i.sku=v_res.sku\n   and (upper(i.sku)=upper(trim(p_scanned_code)) or upper(nullif(p.barcode,''''))=upper(trim(p_scanned_code)));\n if not found then raise exception ''K2_PACKING_ALLOCATION_INVALID'' using errcode=''23514''; end if;\n select * into v_batch from public.product_batches where id=v_res.batch_id and sku=v_res.sku for update;\n if not found or v_batch.inventory_status is distinct from ''available''\n   or v_batch.quantity is null or v_batch.reserved_quantity is null or v_batch.quantity<v_batch.reserved_quantity\n   or v_batch.reserved_quantity<v_res.quantity\n   or v_batch.reserved_quantity<(select coalesce(sum(r.quantity),0) from public.inventory_reservations r where r.batch_id=v_batch.id and r.status=''active'')\n   or not k2_private.lot_is_eligible_v1(v_batch) then\n  raise exception ''K2_PACKING_ALLOCATION_INVALID'' using errcode=''23514''; end if;\n update public.inventory_reservations set packed_quantity=packed_quantity+1,updated_at=v_k2_instant where id=v_res.id;\n select coalesce(max(scan_number),0)+1 into v_scan from public.packing_scan_events where order_request_item_id=v_line.id;\n insert into public.packing_scan_events(order_request_id,order_request_item_id,reservation_id,batch_id,sku,scanned_code,scan_number,actor_id, created_at)\n  values(v_order.id,v_line.id,v_res.id,v_batch.id,v_line.sku,trim(p_scanned_code),v_scan,auth.uid(), v_k2_instant);\n select coalesce(sum(packed_quantity),0) into v_total from public.inventory_reservations where order_request_item_id=v_line.id and status=''active'';\n if v_total=v_line.quantity then update public.orders set order_status=''Packed'' where order_request_id=v_order.id and sku=v_line.sku and order_status::text=''Pending''; end if;\n select exists(select 1 from public.order_request_items where order_request_id=v_order.id)\n   and not exists(select 1 from public.order_request_items i where i.order_request_id=v_order.id\n    and i.quantity<>coalesce((select sum(r.packed_quantity) from public.inventory_reservations r where r.order_request_item_id=i.id and r.status=''active''),0)) into v_complete;\n if v_complete then update public.order_requests set delivery_status=''packed'',updated_at=v_k2_instant where id=v_order.id; end if;\n insert into public.order_request_events(order_request_id,from_status,to_status,actor_id,metadata, created_at)\n  values(v_order.id,''confirmed'',''confirmed'',auth.uid(),jsonb_build_object(''event'',''unit_packed'',''sku'',v_line.sku,\n   ''batch_id'',v_batch.id,''reservation_id'',v_res.id,''physical_lot_confirmed'',true,''scan_number'',v_scan), v_k2_instant);\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n return jsonb_build_object(''order_reference'',v_order.public_reference,''sku'',v_line.sku,''product_name'',v_line.product_name,\n  ''packed_quantity'',v_total,''required_quantity'',v_line.quantity,''line_complete'',v_total=v_line.quantity,''order_complete'',v_complete,''batch_id'',v_batch.id);\nend;\n"},{"signature":"public.fulfill_order_request(uuid, text)","before":"073c29130dfc9f82dc4a5cd117b8a350","after":"037c7d2490d2be6efa98cf5d4fe9bb61","metadata":{"proacl":["postgres=X/postgres","authenticated=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"fulfill_order_request","prorows":0,"pronargs":2,"proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":["p_order_request_id","p_handover_note"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":0},"body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_res public.inventory_reservations;\n  v_summary record;\n  v_balance public.inventory_balances; v_handover_reservation_ids uuid[];\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() then raise exception ''Staff access required''; end if;\n  if nullif(trim(coalesce(p_handover_note, '''')), '''') is null then raise exception ''Courier or handover note is required''; end if;\n  select * into v_order from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n  if v_order.status = ''fulfilled'' then return v_order; end if;\n  if v_order.status <> ''confirmed'' then raise exception ''Order request is not confirmed''; end if;\n  if v_order.payment_status is distinct from ''verified'' then raise exception ''Payment must be explicitly verified before fulfillment''; end if;\n  if coalesce(v_order.shipping_quote_status,'''') not in (''platform_charged'', ''customer_confirmed'', ''waived'') then\n    raise exception ''Delivery charge or customer confirmation is still pending'';\n  end if;\n\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  -- Lock all affected rows before validating, in the prepared release order.\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN''\n   and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id)\n   order by b.sku for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id\n   order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.id in(\n   select batch_id from public.inventory_reservations where order_request_id=v_order.id and status=''active'')\n   order by b.sku,b.id for update;\n  select array_agg(id) into v_handover_reservation_ids from public.inventory_reservations\n   where order_request_id=v_order.id and status=''active'';\n  if not exists(select 1 from public.order_request_items where order_request_id=v_order.id)\n   or exists(select 1 from public.order_request_items i where i.order_request_id=v_order.id\n    and (i.quantity is null or i.quantity<=0 or i.quantity<>coalesce((select sum(r.quantity)\n      from public.inventory_reservations r where r.order_request_id=v_order.id\n      and r.order_request_item_id=i.id and r.sku=i.sku and r.status=''active''\n      and r.packed_quantity=r.quantity),0)))\n   or exists(select 1 from public.inventory_reservations r\n    left join public.order_request_items i on i.id=r.order_request_item_id and i.order_request_id=v_order.id and i.sku=r.sku\n    left join public.product_batches b on b.id=r.batch_id and b.sku=r.sku\n    left join public.inventory_balances bal on bal.sku=r.sku and bal.location_code=''MANILA_MAIN''\n    where r.id=any(v_handover_reservation_ids) and (i.id is null or b.id is null or bal.sku is null\n     or r.quantity<=0 or r.packed_quantity is distinct from r.quantity\n     or b.inventory_status is distinct from ''available''\n     or b.quantity<b.reserved_quantity or b.reserved_quantity<(select sum(x.quantity) from public.inventory_reservations x where x.batch_id=b.id and x.status=''active'')\n     or bal.on_hand<bal.reserved or bal.reserved<(select sum(x.quantity) from public.inventory_reservations x where x.order_request_id=v_order.id and x.sku=r.sku and x.status=''active'')\n     or not k2_private.lot_is_eligible_v1(b))) then\n   raise exception ''K2_RESERVATION_RECONCILIATION_REQUIRED'' using errcode=''23514'';\n  end if;\n  -- K2_HANDOVER_STOCK_COMMITMENT_V1\n  -- Locked exact allocations must already carry attributable ownership evidence.\n  -- Never backfill a historical sale or deduct ownership for the first time at dispatch.\n  if exists(select 1 from public.inventory_reservations r where r.id=any(v_handover_reservation_ids)\n    and (r.committed_at is null or r.committed_by is null\n      or not coalesce(r.commit_cause in (''confirmation'',''payment_verification''),false))) then\n    raise exception ''K2_RESERVATION_RECONCILIATION_REQUIRED'' using errcode=''23514'';\n  end if;\n  if exists (select 1 from public.inventory_reservations where order_request_id = v_order.id and status = ''active'' and packed_quantity <> quantity) then\n    raise exception ''Every required unit must be scanned before fulfillment'';\n  end if;\n  if exists (\n    select 1 from public.inventory_reservations r join public.product_batches b on b.id = r.batch_id\n    where r.order_request_id = v_order.id and r.status = ''active''\n      and not k2_private.lot_is_eligible_v1(b)\n  ) then raise exception ''A reserved lot is no longer sellable; resolve the inventory exception first''; end if;\n\n  for v_res in select * from public.inventory_reservations where order_request_id = v_order.id and status = ''active'' for update\n  loop\n    update public.product_batches\n    set quantity = quantity - v_res.quantity,\n        reserved_quantity = reserved_quantity - v_res.quantity,\n        inventory_status = case when quantity - v_res.quantity = 0 then ''depleted'' else inventory_status end,\n        updated_at = v_k2_instant\n    where id = v_res.batch_id and quantity >= v_res.quantity and reserved_quantity >= v_res.quantity;\n    if not found then raise exception ''Exact lot quantity mismatch for %'', v_res.sku; end if;\n    update public.inventory_reservations set status = ''fulfilled'', updated_at = v_k2_instant where id = v_res.id;\n  end loop;\n\n  for v_summary in select sku, sum(quantity)::integer quantity\n    from public.inventory_reservations where id = any(v_handover_reservation_ids) group by sku\n  loop\n    update public.inventory_balances\n    set on_hand = on_hand - v_summary.quantity, reserved = reserved - v_summary.quantity, updated_at = v_k2_instant\n    where sku = v_summary.sku and location_code = ''MANILA_MAIN''\n      and on_hand >= v_summary.quantity and reserved >= v_summary.quantity;\n    if not found then raise exception ''Inventory balance mismatch for %'', v_summary.sku; end if;\n    select * into v_balance from public.inventory_balances where sku = v_summary.sku and location_code = ''MANILA_MAIN'';\n    perform set_config(''k2.allow_stock_write'', ''on'', true);\n    update public.products set stock_available = (\n      select coalesce(sum(b.quantity - b.reserved_quantity), 0)::integer from public.product_batches b\n      where b.sku = v_summary.sku and b.inventory_status = ''available''\n        and k2_private.lot_is_eligible_v1(b)\n    ) where sku = v_summary.sku;\n    insert into public.inventory_events (sku, location_code, event_type, quantity, reference_type, reference_id, reason, actor_id, created_at)\n    values (v_summary.sku, ''MANILA_MAIN'', ''fulfilled'', v_summary.quantity, ''order_request'', v_order.id, p_handover_note, auth.uid(), v_k2_instant);\n  end loop;\n\n  update public.orders set order_status = ''Shipped''::order_status_enum where order_request_id = v_order.id;\n  update public.coupon_redemptions set status = ''redeemed'', updated_at = v_k2_instant\n  where order_request_id = v_order.id and status = ''reserved'';\n  update public.order_requests\n  set status = ''fulfilled'', delivery_status = ''handed_to_courier'', fulfilled_at = v_k2_instant, updated_at = v_k2_instant\n  where id = v_order.id returning * into v_order;\n  insert into public.order_request_events (order_request_id, from_status, to_status, reason, actor_id, created_at)\n  values (v_order.id, ''confirmed'', ''fulfilled'', p_handover_note, auth.uid(), v_k2_instant);\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return v_order;\nend;\n"},{"signature":"public.extend_reservation_v1(uuid, integer, text)","before":"c93b14351d3496b487ee75422d3d1d15","after":"4974dea8ed2418f1d7876abc649eebb7","metadata":{"proacl":["postgres=X/postgres","authenticated=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"extend_reservation_v1","prorows":1000,"pronargs":3,"proconfig":["search_path=\"\""],"proretset":true,"prosecdef":true,"proargmodes":["i","i","i","t","t","t"],"proargnames":["p_reservation_id","p_minutes","p_reason","reservation_id","expires_at","extension_count"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":0},"body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_row public.inventory_reservations;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() then\n    raise exception ''STAFF_REQUIRED'' using errcode = ''42501'';\n  end if;\n  -- OWNER-002: no less than 30 minutes, no more than 7 days.\n  if p_minutes is null or p_minutes < 30 or p_minutes > 10080 then\n    raise exception ''RESERVATION_EXTENSION_OUT_OF_BOUNDS'' using errcode = ''22023'';\n  end if;\n  if char_length(btrim(coalesce(p_reason, ''''))) < 10 then\n    raise exception ''RESERVATION_EXTENSION_REASON_REQUIRED'' using errcode = ''22023'';\n  end if;\n\n  perform 1 from public.order_requests where id=(select order_request_id from public.inventory_reservations where id=p_reservation_id) for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku=(select sku from public.inventory_reservations where id=p_reservation_id) order by b.sku for update;\n  perform 1 from public.products p where p.sku=(select sku from public.inventory_reservations where id=p_reservation_id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations where id=p_reservation_id for update;\n  perform 1 from public.product_batches b where b.sku=(select sku from public.inventory_reservations where id=p_reservation_id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  select * into v_row from public.inventory_reservations\n  where id = p_reservation_id for update;\n  if not found then\n    raise exception ''RESERVATION_NOT_FOUND'' using errcode = ''22023'';\n  end if;\n  if v_row.status <> ''active'' then\n    raise exception ''RESERVATION_NOT_ACTIVE'' using errcode = ''22023'';\n  end if;\n  if v_row.expires_at is null then\n    raise exception ''RESERVATION_HAS_NO_DEADLINE'' using errcode = ''22023'';\n  end if;\n  -- K2_EXTEND_COMMITTED_RESERVATION_GUARD_V1: committed reservations are owned stock and never expire.\n  if v_row.committed_at is not null then\n    raise exception ''RESERVATION_ALREADY_COMMITTED'' using errcode = ''22023'';\n  end if;\n  -- Refuse to revive. Staff must create a new reservation instead.\n  if v_row.expires_at <= v_k2_instant then\n    raise exception ''RESERVATION_ALREADY_EXPIRED'' using errcode = ''22023'';\n  end if;\n\n  if not exists(select 1 from public.product_batches b where b.id=v_row.batch_id and b.sku=v_row.sku and k2_private.lot_is_eligible_v1(b)) then\n    raise exception using errcode=''23514'',message=''K2_RESERVATION_RECONCILIATION_REQUIRED'';\n  end if;\n  update public.inventory_reservations\n  set expires_at = v_row.expires_at + make_interval(mins => p_minutes),\n      extension_count = v_row.extension_count + 1,\n      last_extended_at = v_k2_instant,\n      last_extended_by = auth.uid(),\n      last_extension_reason = btrim(p_reason),\n      updated_at = v_k2_instant\n  where id = p_reservation_id\n  returning id, inventory_reservations.expires_at, inventory_reservations.extension_count\n  into reservation_id, expires_at, extension_count;\n\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return next;\nend;\n"},{"signature":"public.release_expired_reservations_v1(integer)","before":"5d36ee8ddf79a6f4524919872c63c8d7","after":"0f52cf814525ab5dad9a70955419c008","metadata":{"proacl":["postgres=X/postgres","authenticated=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"release_expired_reservations_v1","prorows":1000,"pronargs":1,"proconfig":["search_path=\"\""],"proretset":true,"prosecdef":true,"proargmodes":["i","t","t"],"proargnames":["p_limit","released_count","released_ids"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":1},"body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_orders uuid[] := ''{}'';\n  v_ids uuid[] := ''{}'';\n  v_summary record;\n  v_res public.inventory_reservations;\n  v_count integer := 0;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() then raise exception ''STAFF_REQUIRED'' using errcode=''42501''; end if;\n  if p_limit is null or p_limit<1 or p_limit>5000 then raise exception ''RELEASE_LIMIT_INVALID'' using errcode=''22023''; end if;\n  -- The limit bounds complete orders, not arbitrary reservation fragments.\n  -- Lock orders before their inventory so confirmation/cancellation serializes.\n  for v_order in\n    select o.* from public.order_requests o\n    where o.status=''submitted'' and o.payment_status in (''unpaid'',''not_requested'',''awaiting_instructions'',''failed'')\n      and exists(select 1 from public.inventory_reservations r where r.order_request_id=o.id\n        and r.status=''active'' and r.expires_at<=clock_timestamp())\n      and not exists(select 1 from public.inventory_reservations r where r.order_request_id=o.id\n        and r.status=''active'' and (r.packed_quantity>0 or r.expires_at is null or r.committed_at is not null))\n    order by o.id limit p_limit for update of o skip locked\n  loop\n    v_orders := array_append(v_orders,v_order.id);\n  end loop;\n  -- Acquire all affected balances before reservation/batch updates. Common SKU\n  -- order across this batch avoids reverse basket order within the sweep.\n  perform 1 from public.inventory_balances b\n    where b.location_code=''MANILA_MAIN'' and b.sku in (\n      select r.sku from public.inventory_reservations r where r.order_request_id=any(v_orders) and r.status=''active''\n    ) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select r.sku from public.inventory_reservations r where r.order_request_id=any(v_orders) and r.status=''active'') order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=any(v_orders) and r.status=''active''\n    order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select r.sku from public.inventory_reservations r where r.order_request_id=any(v_orders) and r.status=''active'') order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  -- An extension may have committed while the sweep waited for these rows.\n  -- Decide again from the now-locked facts; the earlier selection is not proof.\n  select coalesce(array_agg(o.id),''{}''::uuid[]) into v_orders from public.order_requests o\n    where o.id=any(v_orders) and o.status=''submitted''\n      and o.payment_status in (''unpaid'',''not_requested'',''awaiting_instructions'',''failed'')\n      and exists(select 1 from public.inventory_reservations r where r.order_request_id=o.id\n        and r.status=''active'' and r.expires_at<=v_k2_instant)\n      and not exists(select 1 from public.inventory_reservations r where r.order_request_id=o.id\n        and r.status=''active'' and (r.packed_quantity>0 or r.expires_at is null or r.committed_at is not null));\n  perform 1 from public.product_batches b where b.id in (\n    select batch_id from public.inventory_reservations where order_request_id=any(v_orders) and status=''active''\n  ) order by b.sku,b.id for update;\n\n  for v_summary in select r.order_request_id,r.sku,sum(r.quantity)::integer quantity\n    from public.inventory_reservations r where r.order_request_id=any(v_orders) and r.status=''active''\n    group by r.order_request_id,r.sku order by r.sku,r.order_request_id\n  loop\n    update public.inventory_balances set reserved=reserved-v_summary.quantity,updated_at=v_k2_instant\n      where sku=v_summary.sku and location_code=''MANILA_MAIN'' and reserved>=v_summary.quantity;\n    if not found then raise exception ''K2_RESERVATION_BALANCE_MISMATCH'' using errcode=''23514''; end if;\n    for v_res in select * from public.inventory_reservations\n      where order_request_id=v_summary.order_request_id and sku=v_summary.sku and status=''active''\n      order by batch_id,id\n    loop\n      update public.product_batches set reserved_quantity=reserved_quantity-v_res.quantity,updated_at=v_k2_instant\n        where id=v_res.batch_id and sku=v_res.sku and reserved_quantity>=v_res.quantity;\n      if not found then raise exception ''K2_RESERVATION_LOT_MISMATCH'' using errcode=''23514''; end if;\n      update public.inventory_reservations set status=''released'',released_at=v_k2_instant,\n        release_cause=''expired'',updated_at=v_k2_instant where id=v_res.id;\n      v_ids:=array_append(v_ids,v_res.id); v_count:=v_count+1;\n    end loop;\n    perform set_config(''k2.allow_stock_write'',''on'',true);\n    update public.products set stock_available=(\n      select coalesce(sum(b.quantity-b.reserved_quantity),0)::integer from public.product_batches b\n      where b.sku=v_summary.sku and b.inventory_status=''available''\n        and k2_private.lot_is_eligible_v1(b)\n    ) where sku=v_summary.sku;\n    insert into public.inventory_events(sku,location_code,event_type,quantity,reference_type,reference_id,reason,actor_id, created_at)\n      values(v_summary.sku,''MANILA_MAIN'',''reservation_released'',v_summary.quantity,''order_request'',\n        v_summary.order_request_id,''Expired unpaid purchase hold; released the complete order allocation.'',auth.uid(), v_k2_instant);\n  end loop;\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return query select v_count,v_ids;\nend;\n"}]'::jsonb)
  as x(signature text,before text,after text,metadata jsonb,body text) loop
  select * into b from pg_catalog.pg_proc where oid=to_regprocedure(t.signature);
  select jsonb_object_agg(k,to_jsonb(b)->k) into metadata from jsonb_object_keys(t.metadata) k;
  if b.oid is null or pg_catalog.pg_get_userbyid(b.proowner)<>'postgres'
   or md5(replace(b.prosrc,chr(13),''))<>t.before or metadata is distinct from t.metadata then
   raise exception 'K2_GUEST_OPERATIONS_FUNCTION_DRIFT: %',t.signature;
  end if;
 end loop;
 for r in select * from (values
  ('k2_private.guest_request_nonces',false,array['action','nonce','used_at','expires_at']::text[]),
  ('k2_private.category_lot_command_context',true,array['backend_pid','transaction_id','actor_id','maximum_depth','evaluation_instant']::text[])
 ) x(name,rls,columns) loop
  if not exists(select 1 from pg_catalog.pg_class c where c.oid=to_regclass(r.name)
   and c.relkind='r' and pg_catalog.pg_get_userbyid(c.relowner)='postgres'
   and c.relrowsecurity=r.rls and not c.relforcerowsecurity
   and c.relacl::text[]=array['postgres=arwdDxtm/postgres']::text[])
   or (select array_agg(attname::text order by attnum) from pg_catalog.pg_attribute
    where attrelid=to_regclass(r.name) and attnum>0 and not attisdropped) is distinct from r.columns then
   raise exception 'K2_GUEST_OPERATIONS_RELATION_DRIFT: %',r.name;
  end if;
 end loop;
 if exists(select 1 from k2_private.category_lot_command_context) then
  raise exception 'K2_GUEST_OPERATIONS_CONTEXT_NOT_EMPTY';
 end if;
 alter table k2_private.guest_request_nonces
  add column verified_backend_pid integer,
  add column verified_transaction_id xid8,
  add constraint guest_nonce_verified_binding_pair check
   ((verified_backend_pid is null)=(verified_transaction_id is null));
 alter table k2_private.category_lot_command_context
  alter column actor_id drop not null,
  add column authority_kind text not null default 'staff',
  add column guest_nonce uuid,
  add constraint category_context_authority check
   ((authority_kind='staff' and actor_id is not null and guest_nonce is null)
    or (authority_kind='guest' and guest_nonce is not null));
 for t in select * from jsonb_to_recordset('[{"signature":"k2_private.verify_guest_bff_request(text, bigint, uuid, text, text, text)","before":"808cec5d3a1be42e5b7e1ded833cc94f","after":"c3f66c3854464d3b0d03b26f445b432e","metadata":{"proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"verify_guest_bff_request","prorows":0,"pronargs":6,"proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":["p_action","p_timestamp","p_nonce","p_payload_text","p_ip_hash","p_signature"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":0},"body":"\ndeclare\n  v_secret bytea;\n  v_payload_hash text;\n  v_expected text;\n  v_message text;\nbegin\n  if p_timestamp is null or p_nonce is null or p_ip_hash is null or p_signature is null then\n    raise exception using errcode=''28000'', message=''K2_GUEST_SIGNATURE_INVALID'';\n  end if;\n  if p_action is null or p_action not in (''delivery_quote'',\n    ''order'',''pasabuy'',''coupon'',''guest_start'',''guest_read'',''guest_reply'',\n    ''account_claim'',''account_read'',''account_reply'',''wholesale_inquiry'',\n    ''account_settings_read'',''account_settings_write'',''account_notification_read''\n  ) then\n    raise exception using errcode=''22023'', message=''K2_GUEST_ACTION_INVALID'';\n  end if;\n  if p_payload_text is null or octet_length(convert_to(p_payload_text,''UTF8'')) > 24576 then\n    raise exception using errcode=''22023'', message=''K2_GUEST_PAYLOAD_INVALID'';\n  end if;\n  if p_ip_hash !~ ''^[0-9a-f]{64}$'' or p_signature !~ ''^[0-9a-f]{64}$'' then\n    raise exception using errcode=''28000'', message=''K2_GUEST_SIGNATURE_INVALID'';\n  end if;\n  if abs(extract(epoch from clock_timestamp())::bigint - p_timestamp) > 300 then\n    raise exception using errcode=''28000'', message=''K2_GUEST_SIGNATURE_EXPIRED'';\n  end if;\n  select request_secret into v_secret from k2_private.guest_bff_secrets where singleton=true;\n  if v_secret is null then\n    raise exception using errcode=''55000'', message=''K2_GUEST_BOUNDARY_NOT_CONFIGURED'';\n  end if;\n  v_payload_hash:=encode(extensions.digest(convert_to(p_payload_text,''UTF8''),''sha256''),''hex'');\n  v_message:=p_action||E''\\n''||p_timestamp::text||E''\\n''||p_nonce::text||E''\\n''||v_payload_hash||E''\\n''||p_ip_hash;\n  v_expected:=encode(extensions.hmac(convert_to(v_message,''UTF8''),v_secret,''sha256''),''hex'');\n  if extensions.digest(convert_to(v_expected,''UTF8''),''sha256'')\n     is distinct from extensions.digest(convert_to(p_signature,''UTF8''),''sha256'') then\n    raise exception using errcode=''28000'', message=''K2_GUEST_SIGNATURE_INVALID'';\n  end if;\n  delete from k2_private.guest_request_nonces where expires_at <= now();\n  insert into k2_private.guest_request_nonces(action,nonce,expires_at,verified_backend_pid,verified_transaction_id)\n  values(p_action,p_nonce,now()+interval ''10 minutes'',pg_catalog.pg_backend_pid(),pg_catalog.pg_current_xact_id()) on conflict do nothing;\n  return found;\nend;\n"},{"signature":"k2_private.start_category_lot_context_v1(integer)","before":"195f64f80687ee1a932d415ff4e48238","after":"fa779caddabc8215c824b1bcf6cfb3ad","metadata":{"proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"start_category_lot_context_v1","prorows":0,"pronargs":1,"proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":["p_maximum_depth"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":0},"body":"\ndeclare v_instant timestamptz;\nbegin\n if p_maximum_depth is null or p_maximum_depth<1 then\n  raise exception using errcode=''22023'',message=''K2_CATEGORY_CONTEXT_INPUT_INVALID'';\n end if;\n if auth.uid() is null or not public.is_staff() then\n  raise exception using errcode=''42501'',message=''K2_STAFF_REQUIRED'';\n end if;\n if coalesce(auth.jwt()->>''aal'','''')<>''aal2'' then\n  raise exception using errcode=''42501'',message=''K2_AAL2_REQUIRED'';\n end if;\n -- Verify an existing boundary; never acquire a late policy lock here.\n if not exists(select 1 from pg_catalog.pg_locks l where l.pid=pg_catalog.pg_backend_pid()\n  and l.locktype=''advisory'' and l.classid=1261585232::oid and l.objid=1347374169::oid\n  and l.objsubid=2 and l.granted and l.mode in (''ShareLock'',''ExclusiveLock'')) then\n  raise exception using errcode=''55000'',message=''K2_CATEGORY_CONTEXT_ENTRY_REQUIRED'';\n end if;\n if exists(select 1 from k2_private.category_lot_command_context\n  where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n  raise exception using errcode=''55000'',message=''K2_CATEGORY_CONTEXT_ALREADY_SET'';\n end if;\n v_instant:=pg_catalog.clock_timestamp();\n insert into k2_private.category_lot_command_context\n (backend_pid,transaction_id,actor_id,maximum_depth,evaluation_instant,authority_kind,guest_nonce)\n values(pg_catalog.pg_backend_pid(),pg_catalog.pg_current_xact_id(),auth.uid(),p_maximum_depth,v_instant,''staff'',null);\n return v_instant;\nend "},{"signature":"k2_private.current_category_lot_context_v1()","before":"8354367b47bf437c8f0e7cda37417eab","after":"0ace340532be2d89ba8b2230e37f245f","metadata":{"proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"current_category_lot_context_v1","prorows":0,"pronargs":0,"proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":null,"proisstrict":false,"proparallel":"u","provolatile":"s","proleakproof":false,"pronargdefaults":0},"body":"\ndeclare v_context k2_private.category_lot_command_context;\nbegin\n select * into v_context from k2_private.category_lot_command_context\n  where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id();\n if not found then raise exception using errcode=''55000'',message=''K2_CATEGORY_CONTEXT_REQUIRED'';end if;\n if v_context.actor_id is distinct from auth.uid() then\n  raise exception using errcode=''42501'',message=''K2_CATEGORY_CONTEXT_ACTOR_MISMATCH'';\n end if;\n if v_context.authority_kind=''guest'' then\n  if not exists(select 1 from k2_private.guest_request_nonces n\n  where n.action=''order'' and n.nonce=v_context.guest_nonce\n   and n.verified_backend_pid=pg_catalog.pg_backend_pid()\n   and n.verified_transaction_id=pg_catalog.pg_current_xact_id()\n   and n.expires_at>pg_catalog.clock_timestamp()) then\n   raise exception using errcode=''42501'',message=''K2_GUEST_CONTEXT_PROOF_REQUIRED'';\n  end if;\n elsif v_context.authority_kind=''staff'' then\n  if not public.is_staff() then raise exception using errcode=''42501'',message=''K2_STAFF_REQUIRED'';end if;\n  if coalesce(auth.jwt()->>''aal'','''')<>''aal2'' then raise exception using errcode=''42501'',message=''K2_AAL2_REQUIRED'';end if;\n else\n  raise exception using errcode=''42501'',message=''K2_CATEGORY_CONTEXT_AUTHORITY_INVALID'';\n end if;\n return v_context;\nend "},{"signature":"k2_private.clear_category_lot_context_v1()","before":"2eeb3aa429998a8cef36782ef6b83b71","after":"d4bae070672f12c882b0d729f0fb9c4f","metadata":{"proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"clear_category_lot_context_v1","prorows":0,"pronargs":0,"proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":null,"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":0},"body":"\nbegin\n perform k2_private.current_category_lot_context_v1();\n delete from k2_private.category_lot_command_context where backend_pid=pg_catalog.pg_backend_pid()\n  and transaction_id=pg_catalog.pg_current_xact_id() and actor_id is not distinct from auth.uid();\nend "},{"signature":"public.submit_guest_order_v1(bigint, uuid, text, text, text, text)","before":"c58cdccacdf786598c891ae191be303b","after":"e4b5a7997a2e7d47a7be3e6d7fbdef79","metadata":{"proacl":["postgres=X/postgres","anon=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"submit_guest_order_v1","prorows":1000,"pronargs":6,"proconfig":["search_path=\"\""],"proretset":true,"prosecdef":true,"proargmodes":["i","i","i","i","i","i","t","t","t","t","t","t","t","t","t","t","t","t"],"proargnames":["p_timestamp","p_nonce","p_payload_text","p_ip_hash","p_signature","p_guest_grant_hash","ok","error_code","retry_after_seconds","public_reference","status","subtotal","discount_amount","total_amount","shipping_quote_status","delivery_status","created_at","guest_grant_token"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":1},"body":"\ndeclare\n  v_payload jsonb;\n  v_order public.order_requests;\n  v_identity record;\n  v_conversation_id uuid;\n  v_message_id uuid;\n  v_ip bytea;\n  v_contact bytea;\n  v_rate record;\n  v_fingerprint bytea;\n  v_existing_hash bytea;\n  v_shipping_num numeric;\n  v_depth integer;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not k2_private.verify_guest_bff_request(''order'', p_timestamp, p_nonce, p_payload_text, p_ip_hash, p_signature) then\n    return query select false, ''REQUEST_REPLAYED'', 0, null::text, null::text, null::numeric,\n      null::numeric, null::numeric, null::text, null::text, null::timestamptz, null::text;\n    return;\n  end if;\n  v_payload := p_payload_text::jsonb;\n  v_ip := decode(p_ip_hash, ''hex'');\n  v_contact := k2_private.contact_hash(v_payload);\n  v_fingerprint := extensions.digest(convert_to(p_payload_text, ''UTF8''), ''sha256'');\n  if p_guest_grant_hash ~ ''^[0-9a-f]{64}$'' then v_existing_hash := decode(p_guest_grant_hash, ''hex''); end if;\n\n  select * into v_rate from k2_private.consume_guest_rate(''order'',''ip'',v_ip,900,5);\n  if not v_rate.allowed then\n    return query select false, ''RATE_LIMITED'', v_rate.retry_after_seconds, null::text, null::text,\n      null::numeric, null::numeric, null::numeric, null::text, null::text, null::timestamptz, null::text;\n    return;\n  end if;\n  select * into v_rate from k2_private.consume_guest_rate(''order'',''contact'',v_contact,3600,3);\n  if not v_rate.allowed then\n    return query select false, ''RATE_LIMITED'', v_rate.retry_after_seconds, null::text, null::text,\n      null::numeric, null::numeric, null::numeric, null::text, null::text, null::timestamptz, null::text;\n    return;\n  end if;\n\n  -- Match the canonical writer: serialize the key before inventory/FK locks.\n  perform pg_advisory_xact_lock(hashtextextended(''k2.website-order:''||trim(v_payload->>''idempotencyKey''),0));\n  select * into v_order from public.order_requests\n  where idempotency_key = v_payload->>''idempotencyKey'';\n  if found then\n    if v_order.request_fingerprint is distinct from v_fingerprint then\n      return query select false, ''IDEMPOTENCY_CONFLICT'', 0, null::text, null::text,\n        null::numeric, null::numeric, null::numeric, null::text, null::text, null::timestamptz, null::text;\n    else\n      return query select true, null::text, 0, v_order.public_reference, v_order.status,\n        v_order.subtotal, v_order.discount_amount, v_order.total_amount,\n        v_order.shipping_quote_status, v_order.delivery_status, v_order.created_at, null::text;\n    end if;\n    return;\n  end if;\n\n  -- Saved receipt/conflict above skips fresh policy configuration and stock.\n  perform 1 from public.coupons\n   where code=upper(trim(v_payload->>''couponCode'')) for update;\n  perform k2_private.require_website_order_items(v_payload->''items'');\n  perform 1 from public.product_batches b\n   where b.sku in(select item->>''sku'' from jsonb_array_elements(v_payload->''items'') item)\n   order by b.sku,b.id for update;\n  if exists(select 1 from public.inventory_balances b\n   where b.location_code=''MANILA_MAIN''\n    and b.sku in(select item->>''sku'' from jsonb_array_elements(v_payload->''items'') item)\n    and (b.on_hand<0 or b.reserved<0 or b.reserved>b.on_hand)) then\n   raise exception using errcode=''23514'',message=''K2_RESERVATION_BALANCE_MISMATCH'';\n  end if;\n  select maximum_depth into v_depth from k2_private.category_policy_command_config where singleton;\n  if v_depth is null or v_depth<1 then\n   raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n  end if;\n  perform k2_private.start_guest_category_lot_context_v1(v_depth,p_nonce);\n  select * into v_identity from k2_private.resolve_guest_identity(\n    v_payload, ''website_guest'', v_existing_hash\n  );\n  v_order := public.submit_order_request_v2(\n    v_payload->>''customerName'', nullif(v_payload->>''email'',''''), nullif(v_payload->>''phone'',''''),\n    v_payload->>''address'', v_payload->>''fulfillmentMethod'', nullif(v_payload->>''note'',''''),\n    v_payload->''items'', v_payload->>''idempotencyKey'', nullif(v_payload->>''couponCode'','''')\n  );\n\n  -- Apply upfront delivery quotation if provided by checkout\n  if (v_payload->>''shippingAmount'') is not null then\n    begin\n      v_shipping_num := (v_payload->>''shippingAmount'')::numeric;\n      if v_shipping_num >= 0 and v_shipping_num <= 100000 then\n        update public.order_requests as o\n        set shipping_amount = v_shipping_num,\n            shipping_quote_status = coalesce(nullif(v_payload->>''shippingQuoteStatus'',''''), ''customer_confirmed''),\n            total_amount = o.subtotal - o.discount_amount + v_shipping_num,\n            customer_delivery_confirmed_at = now(),\n            updated_at = now()\n        where o.id = v_order.id\n        returning o.* into v_order;\n      end if;\n    exception when others then\n      -- Fall back cleanly to unpriced order request on invalid numeric\n      null;\n    end;\n  end if;\n\n  update public.order_requests set customer_id=v_identity.customer_id,\n    request_fingerprint=v_fingerprint where id=v_order.id returning * into v_order;\n\n  insert into public.conversations(\n    customer_id, customer_name, customer_email, customer_phone, platform, source_kind, source_id\n  ) values (\n    v_identity.customer_id, v_order.customer_name, v_order.customer_email, v_order.customer_phone,\n    ''Website'', ''order_request'', v_order.id\n  )\n  on conflict (source_kind, source_id)\n    where source_kind is not null and source_id is not null\n  do update set\n    customer_id=excluded.customer_id,\n    customer_name=excluded.customer_name,\n    customer_email=excluded.customer_email,\n    customer_phone=excluded.customer_phone,\n    updated_at=now()\n  returning id into v_conversation_id;\n\n  insert into public.messages(\n    conversation_id, sender_type, content, is_draft, delivery_status, provider_event_key, direction\n  )\n  select v_conversation_id, ''Customer'',\n    ''Order '' || v_order.public_reference || '' received through the website. ''\n      || ''Delivery option: '' || coalesce(v_order.fulfillment_method, ''Standard'') || '' (₱'' || v_order.shipping_amount::text || ''). ''\n      || ''Total: ₱'' || v_order.total_amount::text || ''. Staff verify Manila stock and contact with payment details.'',\n    false, ''received'', ''guest-order-seed:'' || v_order.id::text, ''inbound''\n  where not exists (\n    select 1 from public.messages\n    where conversation_id = v_conversation_id\n      and (provider_event_key in (''guest-order-seed:'' || v_order.id::text, ''order_seed_'' || v_order.id::text)\n        or external_message_id in (''guest-order-seed:'' || v_order.id::text, ''order_seed_'' || v_order.id::text))\n  )\n  returning id into v_message_id;\n\n  insert into public.conversation_events(\n    conversation_id, event_type, reason, metadata\n  )\n  select v_conversation_id, ''inbound_message'',\n    ''Seeded customer conversation from order submission '' || v_order.public_reference,\n    jsonb_build_object(''order_id'',v_order.id,''public_reference'',v_order.public_reference,''source_kind'',''order_request'')\n  where v_message_id is not null;\n\n  if v_message_id is not null then\n    update public.conversations\n    set unread_count=1,last_inbound_at=now(),response_due_at=now()+interval ''4 hours'',\n      last_message_at=now(),updated_at=now()\n    where id=v_conversation_id;\n  end if;\n\n  insert into public.guest_access_grant_scopes(grant_id,scope_kind,scope_id,permissions)\n  values\n    (v_identity.grant_id,''order_request'',v_order.id,array[''read'']::text[]),\n    (v_identity.grant_id,''conversation'',v_conversation_id,array[''read'',''reply'']::text[])\n  on conflict do nothing;\n\n  perform k2_private.clear_category_lot_context_v1();\n  return query select true, null::text, 0, v_order.public_reference, v_order.status,\n    v_order.subtotal, v_order.discount_amount, v_order.total_amount,\n    v_order.shipping_quote_status, v_order.delivery_status, v_order.created_at,\n    v_identity.raw_grant_token;\nend;\n"},{"signature":"public.confirm_order_request(uuid, text)","before":"91ac2250115d77799fe300cc2e587743","after":"36967b6d0c2f85f25a02f5c351df22a2","metadata":{"proacl":null,"probin":null,"procost":100,"prokind":"f","proname":"confirm_order_request","prorows":0,"pronargs":2,"proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":["p_order_request_id","p_reason"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":1},"body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_line public.order_request_items;\n  v_coupon public.coupons;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() then raise exception ''Staff access required''; end if;\n  select * into v_order from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n  if v_order.status = ''confirmed'' then return v_order; end if;\n  if v_order.status <> ''submitted'' then raise exception ''Only submitted requests can be confirmed''; end if;\n\n  perform 1 from public.coupons where id=v_order.coupon_id for update;\n  insert into public.inventory_balances(sku,location_code,on_hand,reserved)\n  select p.sku,''MANILA_MAIN'',coalesce(sum(b.quantity),0)::integer,coalesce(sum(b.reserved_quantity),0)::integer\n  from public.products p left join public.product_batches b on b.sku=p.sku\n  where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id)\n  group by p.sku order by p.sku on conflict(sku,location_code) do nothing;\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  if v_order.coupon_id is not null then\n    select * into v_coupon from public.coupons where id = v_order.coupon_id for update;\n    if not found or not v_coupon.is_active or v_coupon.archived_at is not null\n       or v_coupon.starts_at > v_k2_instant or (v_coupon.ends_at is not null and v_coupon.ends_at <= v_k2_instant)\n       or (v_coupon.max_redemptions is not null and v_coupon.redemption_count >= v_coupon.max_redemptions) then\n      raise exception ''The coupon is no longer available'';\n    end if;\n    update public.coupons set redemption_count = redemption_count + 1 where id = v_coupon.id;\n    insert into public.coupon_redemptions (coupon_id, order_request_id, discount_amount)\n    values (v_coupon.id, v_order.id, v_order.discount_amount);\n  end if;\n\n  perform public.reserve_order_request_lots_v1(v_order.id, p_reason);\n\n  for v_line in select * from public.order_request_items where order_request_id = v_order.id order by created_at\n  loop\n    insert into public.orders (\n      sku, quantity, channel_source, fulfillment_method, order_status,\n      payment_status, customer_name, customer_email, total_amount, order_request_id\n    ) values (\n      v_line.sku, v_line.quantity,\n      case v_order.channel_source\n        when ''shopee'' then ''shopee''::channel_type\n        when ''lazada'' then ''lazada''::channel_type\n        when ''tiktok'' then ''tiktok''::channel_type\n        else ''website_retail''::channel_type end,\n      v_order.fulfillment_method, ''Pending''::order_status_enum, ''Unpaid''::payment_status_enum,\n      v_order.customer_name, v_order.customer_email, v_line.line_total, v_order.id\n    );\n  end loop;\n\n  update public.order_requests\n  set status = ''confirmed'', confirmed_by = auth.uid(), confirmed_at = v_k2_instant,\n      delivery_status = case when shipping_quote_status in (''platform_charged'', ''customer_confirmed'', ''waived'') then ''ready_to_pack'' else delivery_status end,\n      updated_at = v_k2_instant\n  where id = v_order.id returning * into v_order;\n\n  -- Owned stock leaves the sellable pool here, once. The early return above\n  -- keeps a replayed confirmation from deducting again, and the helper\n  -- itself skips already-committed allocations, so both guards agree.\n  perform public.commit_order_request_stock_v1(v_order.id, ''confirmation'', p_reason);\n\n  insert into public.order_request_events (order_request_id, from_status, to_status, reason, actor_id, created_at)\n  values (v_order.id, ''submitted'', ''confirmed'', p_reason, auth.uid(), v_k2_instant);\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return v_order;\nend;\n"},{"signature":"public.cancel_order_request(uuid, text)","before":"cc96642602da36b41b12ea223b32d1ae","after":"1bf23bd7d10069bc7add637d6a499a5b","metadata":{"proacl":null,"probin":null,"procost":100,"prokind":"f","proname":"cancel_order_request","prorows":0,"pronargs":2,"proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":["p_order_request_id","p_reason"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":0},"body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_res public.inventory_reservations;\n  v_summary record;\n\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() then raise exception ''Staff access required''; end if;\n  if nullif(trim(coalesce(p_reason, '''')), '''') is null then raise exception ''Cancellation reason is required''; end if;\n  select * into v_order from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n  if v_order.status = ''cancelled'' then return v_order; end if;\n  if v_order.status not in (''submitted'', ''confirmed'') then raise exception ''This order request cannot be cancelled''; end if;\n\n  perform 1 from public.coupons where id=v_order.coupon_id for update;\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  -- Submitted purchases hold stock too. Summarize only currently active lots,\n  -- then acquire balance before batch locks in SKU order, as reservation does.\n  for v_summary in select sku, sum(quantity)::integer quantity\n    from public.inventory_reservations\n    where order_request_id = v_order.id and status = ''active''\n    group by sku order by sku\n  loop\n    update public.inventory_balances set reserved = reserved - v_summary.quantity, updated_at = v_k2_instant\n    where sku = v_summary.sku and location_code = ''MANILA_MAIN'' and reserved >= v_summary.quantity;\n    if not found then raise exception ''Inventory reservation mismatch for %'', v_summary.sku; end if;\n\n    for v_res in select * from public.inventory_reservations\n      where order_request_id = v_order.id and status = ''active'' and sku = v_summary.sku\n      order by batch_id, id for update\n    loop\n      update public.product_batches set reserved_quantity = reserved_quantity - v_res.quantity, updated_at = v_k2_instant\n      where id = v_res.batch_id and reserved_quantity >= v_res.quantity;\n      if not found then raise exception ''Lot reservation mismatch for %'', v_res.sku; end if;\n      update public.inventory_reservations\n      set status = ''released'', released_at = v_k2_instant, release_cause = ''cancelled'', updated_at = v_k2_instant\n      where id = v_res.id;\n    end loop;\n\n    perform set_config(''k2.allow_stock_write'', ''on'', true);\n    update public.products set stock_available = (\n      select coalesce(sum(b.quantity - b.reserved_quantity), 0)::integer from public.product_batches b\n      where b.sku = v_summary.sku and b.inventory_status = ''available''\n        and k2_private.lot_is_eligible_v1(b)\n    ) where sku = v_summary.sku;\n    insert into public.inventory_events (sku, location_code, event_type, quantity, reference_type, reference_id, reason, actor_id, created_at)\n    values (v_summary.sku, ''MANILA_MAIN'', ''reservation_released'', v_summary.quantity, ''order_request'', v_order.id, p_reason, auth.uid(), v_k2_instant);\n  end loop;\n\n  update public.orders set order_status = ''Cancelled''::order_status_enum\n  where order_request_id = v_order.id and order_status::text <> ''Shipped'';\n\n  if v_order.coupon_id is not null then\n    update public.coupon_redemptions set status = ''released'', updated_at = v_k2_instant\n    where order_request_id = v_order.id and status = ''reserved'';\n    if found then update public.coupons set redemption_count = greatest(redemption_count - 1, 0) where id = v_order.coupon_id; end if;\n  end if;\n  update public.order_requests\n  set status = ''cancelled'', delivery_status = ''cancelled'', exception_status = ''resolved'',\n      exception_note = trim(p_reason), cancelled_at = v_k2_instant, updated_at = v_k2_instant\n  where id = v_order.id returning * into v_order;\n  insert into public.order_request_events (order_request_id, from_status, to_status, reason, actor_id, created_at)\n  values (v_order.id, case when v_order.confirmed_at is null then ''submitted'' else ''confirmed'' end, ''cancelled'', p_reason, auth.uid(), v_k2_instant);\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return v_order;\nend;\n"},{"signature":"public.set_order_request_payment_status(uuid, text, text, jsonb)","before":"c124b51c31ad80cd558bf686282c3f82","after":"c7be6e145bec58a0a94df70a5980868b","metadata":{"proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"set_order_request_payment_status","prorows":0,"pronargs":4,"proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":["p_order_request_id","p_to_status","p_evidence_note","p_payment_evidence"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":0},"body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_from text;\n  v_submitter uuid;\n  v_structured_evidence jsonb := ''{}''::jsonb;\n  v_method text;\n  v_amount numeric;\n  v_currency text;\n  v_payer_name text;\n  v_payment_reference text;\n  v_proof_asset_ref text;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() or auth.uid() is null\n     or coalesce(auth.jwt()->>''aal'','''') <> ''aal2'' then\n    raise exception using errcode=''42501'', message=''K2_ADMIN_AAL2_REQUIRED'';\n  end if;\n\n  select * into v_order from public.order_requests where id=p_order_request_id for update;\n  if not found then raise exception using errcode=''23514'', message=''K2_PAYMENT_ORDER_INELIGIBLE''; end if;\n  v_from := v_order.payment_status;\n  if p_to_status = v_from then return v_order; end if;\n\n  if not coalesce((\n    (v_from=''not_requested'' and p_to_status=''awaiting_instructions'') or\n    (v_from=''awaiting_instructions'' and p_to_status in (''evidence_submitted'',''failed'')) or\n    (v_from=''evidence_submitted'' and p_to_status in (''verified'',''failed'')) or\n    (v_from=''failed'' and p_to_status=''evidence_submitted'') or\n    (v_from=''verified'' and p_to_status=''refunded'')\n  ), false) then\n    raise exception using errcode=''23514'', message=''K2_PAYMENT_TRANSITION_INVALID'';\n  end if;\n\n  if length(trim(coalesce(p_evidence_note,''''))) > 1000 or\n     (p_to_status not in (''awaiting_instructions'', ''evidence_submitted'') and nullif(trim(coalesce(p_evidence_note,'''')),'''') is null) then\n    raise exception using errcode=''23514'', message=''K2_PAYMENT_EVIDENCE_REQUIRED'';\n  end if;\n\n  -- Refund reconciliation remains available for a verified cancelled/fulfilled order;\n  -- all new attempts and collection/verification require an open order.\n  if p_to_status <> ''refunded'' and v_order.status not in (''submitted'',''confirmed'') then\n    raise exception using errcode=''23514'', message=''K2_PAYMENT_ORDER_INELIGIBLE'';\n  end if;\n\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  if p_to_status in (''evidence_submitted'',''verified'') then\n    -- K2_PAYMENT_BALANCE_INTEGRITY_V1\n    perform 1 from public.order_request_items where order_request_id=v_order.id order by id for update;\n    perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN''\n      and b.sku in (select sku from public.order_request_items where order_request_id=v_order.id)\n      order by b.sku for update;\n    perform 1 from public.inventory_reservations where order_request_id=v_order.id order by sku,batch_id,id for update;\n    perform 1 from public.product_batches b where b.id in (\n      select batch_id from public.inventory_reservations where order_request_id=v_order.id and status=''active''\n    ) order by b.sku,b.id for update;\n\n    if exists (\n      select 1 from public.order_request_items i\n      left join public.inventory_balances b on b.sku=i.sku and b.location_code=''MANILA_MAIN''\n      where i.order_request_id=v_order.id and (\n        b.sku is null or b.reserved is null or b.on_hand is null\n        or b.reserved<0 or b.reserved>b.on_hand\n        or b.reserved<(select coalesce(sum(r.quantity),0) from public.inventory_reservations r\n          where r.order_request_id=v_order.id and r.sku=i.sku and r.status=''active'')\n      )\n    ) then\n      raise exception using errcode=''23514'', message=''K2_PAYMENT_STOCK_INELIGIBLE'';\n    end if;\n\n    if not exists(select 1 from public.order_request_items where order_request_id=v_order.id)\n      or exists (\n        select 1 from public.inventory_reservations r\n        left join public.order_request_items i on i.id=r.order_request_item_id and i.order_request_id=v_order.id and i.sku=r.sku\n        left join public.product_batches b on b.id=r.batch_id and b.sku=r.sku\n        where r.order_request_id=v_order.id and r.status=''active''\n          and (i.id is null or b.id is null or r.quantity<=0\n            or ((r.committed_at is not null or r.committed_by is not null or r.commit_cause is not null)\n              and not coalesce(r.committed_at is not null and r.committed_by is not null\n                and r.commit_cause in (''confirmation'',''payment_verification''),false))\n            or (r.committed_at is null and (r.expires_at is null or r.expires_at<=v_k2_instant))\n            or b.reserved_quantity < (select sum(r2.quantity) from public.inventory_reservations r2 where r2.batch_id=b.id and r2.status=''active''))\n      )\n      or exists (\n        select 1 from public.order_request_items i where i.order_request_id=v_order.id\n        and i.quantity <> coalesce((\n          select sum(r.quantity) from public.inventory_reservations r\n          join public.product_batches b on b.id=r.batch_id and b.sku=r.sku\n          where r.order_request_id=v_order.id and r.order_request_item_id=i.id and r.sku=i.sku\n            and r.status=''active'' and r.quantity>0\n            and (r.committed_at is not null or r.expires_at>v_k2_instant)\n            and b.inventory_status=''available''\n            and b.quantity>=b.reserved_quantity and b.reserved_quantity>=r.quantity\n            and k2_private.lot_is_eligible_v1(b)\n        ),0)\n      ) then\n      raise exception using errcode=''23514'', message=''K2_PAYMENT_STOCK_INELIGIBLE'';\n    end if;\n  end if;\n\n  if p_to_status = ''evidence_submitted'' then\n    if p_payment_evidence is not null and p_payment_evidence <> ''{}''::jsonb then\n      v_method := p_payment_evidence->>''method'';\n      if v_method is null or v_method not in (''gcash'', ''bank_transfer'', ''maya'', ''cash'', ''other'') then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_METHOD_INVALID'';\n      end if;\n\n      begin\n        v_amount := (p_payment_evidence->>''amount'')::numeric;\n      exception when others then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_AMOUNT_INVALID'';\n      end;\n      if v_amount is null or v_amount <= 0 or v_amount > 10000000 then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_AMOUNT_INVALID'';\n      end if;\n\n      v_currency := coalesce(p_payment_evidence->>''currency'', ''PHP'');\n      if v_currency <> ''PHP'' then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_CURRENCY_INVALID'';\n      end if;\n\n      v_payer_name := trim(coalesce(p_payment_evidence->>''payer_name'', ''''));\n      if length(v_payer_name) not between 1 and 140 then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_PAYER_INVALID'';\n      end if;\n\n      v_payment_reference := trim(coalesce(p_payment_evidence->>''payment_reference'', ''''));\n      if length(v_payment_reference) not between 1 and 100 then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_REFERENCE_INVALID'';\n      end if;\n\n      v_proof_asset_ref := trim(coalesce(p_payment_evidence->>''proof_asset_ref'', ''''));\n      if length(v_proof_asset_ref) > 500 then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_PROOF_INVALID'';\n      end if;\n\n      v_structured_evidence := jsonb_build_object(\n        ''method'', v_method,\n        ''amount'', v_amount,\n        ''currency'', v_currency,\n        ''payer_name'', v_payer_name,\n        ''payment_reference'', v_payment_reference,\n        ''proof_asset_ref'', nullif(v_proof_asset_ref, ''''),\n        ''submitted_at'', v_k2_instant,\n        ''submitted_by'', auth.uid()\n      );\n    else\n      -- If structured fields omitted, note must be present\n      if nullif(trim(coalesce(p_evidence_note, '''')), '''') is null then\n        raise exception using errcode=''23514'', message=''K2_PAYMENT_EVIDENCE_REQUIRED'';\n      end if;\n      v_structured_evidence := jsonb_build_object(\n        ''legacy_note'', trim(p_evidence_note),\n        ''submitted_at'', v_k2_instant,\n        ''submitted_by'', auth.uid()\n      );\n    end if;\n\n    update public.order_requests\n    set payment_status = p_to_status,\n        payment_evidence = v_structured_evidence,\n        updated_at = v_k2_instant\n    where id = v_order.id\n    returning * into v_order;\n\n    insert into public.order_request_events(\n      order_request_id, from_status, to_status, reason, actor_id, metadata, created_at\n    )\n    values(\n      v_order.id, v_order.status, v_order.status, trim(coalesce(p_evidence_note, v_payment_reference, '''')),\n      auth.uid(),\n      jsonb_build_object(\n        ''event'', ''payment_status_changed'',\n        ''from'', v_from,\n        ''to'', p_to_status,\n        ''corrected_attempt'', v_from = ''failed'',\n        ''payment_evidence'', v_structured_evidence\n      ),\n      v_k2_instant\n    );\n\n  elsif p_to_status = ''verified'' then\n    select actor_id into v_submitter from public.order_request_events\n      where order_request_id = v_order.id and metadata->>''event'' = ''payment_status_changed''\n        and metadata->>''to'' = ''evidence_submitted''\n      order by created_at desc, id desc limit 1;\n\n    if v_submitter is null or v_submitter = auth.uid() then\n      raise exception using errcode=''42501'', message=''K2_PAYMENT_INDEPENDENT_REVIEW_REQUIRED'';\n    end if;\n\n    -- K2_STRUCTURED_PAYMENT_STOCK_COMMITMENT_V1: after eligibility and distinct review.\n    perform public.commit_order_request_stock_v1(v_order.id,''payment_verification'',p_evidence_note);\n    v_structured_evidence := coalesce(v_order.payment_evidence, ''{}''::jsonb) || jsonb_build_object(\n      ''verified_at'', v_k2_instant,\n      ''verified_by'', auth.uid(),\n      ''verification_note'', trim(p_evidence_note)\n    );\n\n    update public.order_requests\n    set payment_status = p_to_status,\n        payment_evidence = v_structured_evidence,\n        updated_at = v_k2_instant\n    where id = v_order.id\n    returning * into v_order;\n\n    insert into public.order_request_events(\n      order_request_id, from_status, to_status, reason, actor_id, metadata, created_at\n    )\n    values(\n      v_order.id, v_order.status, v_order.status, trim(p_evidence_note),\n      auth.uid(),\n      jsonb_build_object(\n        ''event'', ''payment_status_changed'',\n        ''from'', v_from,\n        ''to'', p_to_status,\n        ''corrected_attempt'', false,\n        ''verification'', jsonb_build_object(\n          ''verified_by'', auth.uid(),\n          ''verified_at'', v_k2_instant,\n          ''note'', trim(p_evidence_note)\n        )\n      ),\n      v_k2_instant\n    );\n\n  else\n    update public.order_requests\n    set payment_status = p_to_status,\n        updated_at = v_k2_instant\n    where id = v_order.id\n    returning * into v_order;\n\n    insert into public.order_request_events(\n      order_request_id, from_status, to_status, reason, actor_id, metadata, created_at\n    )\n    values(\n      v_order.id, v_order.status, v_order.status, trim(coalesce(p_evidence_note, '''')),\n      auth.uid(),\n      jsonb_build_object(\n        ''event'', ''payment_status_changed'',\n        ''from'', v_from,\n        ''to'', p_to_status,\n        ''corrected_attempt'', v_from = ''failed''\n      ),\n      v_k2_instant\n    );\n  end if;\n\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return v_order;\nend;\n"},{"signature":"public.record_packing_scan_exact_v1(uuid, text, uuid, boolean)","before":"84012276355c2d45903c6aec553b6f88","after":"a65edce5045b4b420c1d0068362838bc","metadata":{"proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"record_packing_scan_exact_v1","prorows":0,"pronargs":4,"proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":["p_order_request_id","p_scanned_code","p_reservation_id","p_lot_confirmed"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":0},"body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n v_order public.order_requests; v_res public.inventory_reservations;\n v_line public.order_request_items; v_batch public.product_batches; v_scan integer; v_total integer; v_complete boolean;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n if not public.is_staff() or auth.uid() is null then raise exception ''Staff access required'' using errcode=''42501''; end if;\n if p_lot_confirmed is distinct from true then raise exception ''K2_PACKING_LOT_CONFIRMATION_REQUIRED'' using errcode=''23514''; end if;\n select * into v_order from public.order_requests where id=p_order_request_id for update;\n if not found or v_order.status is distinct from ''confirmed'' then raise exception ''K2_PACKING_ALLOCATION_INVALID'' using errcode=''23514''; end if;\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n select * into v_res from public.inventory_reservations where id=p_reservation_id and order_request_id=v_order.id for update;\n if not found or v_res.status is distinct from ''active'' or v_res.packed_quantity is null\n   or v_res.quantity is null or v_res.quantity<=0 or v_res.packed_quantity<0 or v_res.packed_quantity>=v_res.quantity then\n  raise exception ''K2_PACKING_ALLOCATION_INVALID'' using errcode=''23514''; end if;\n select i.* into v_line from public.order_request_items i join public.products p on p.sku=i.sku\n  where i.id=v_res.order_request_item_id and i.order_request_id=v_order.id and i.sku=v_res.sku\n   and (upper(i.sku)=upper(trim(p_scanned_code)) or upper(nullif(p.barcode,''''))=upper(trim(p_scanned_code)));\n if not found then raise exception ''K2_PACKING_ALLOCATION_INVALID'' using errcode=''23514''; end if;\n select * into v_batch from public.product_batches where id=v_res.batch_id and sku=v_res.sku for update;\n if not found or v_batch.inventory_status is distinct from ''available''\n   or v_batch.quantity is null or v_batch.reserved_quantity is null or v_batch.quantity<v_batch.reserved_quantity\n   or v_batch.reserved_quantity<v_res.quantity\n   or v_batch.reserved_quantity<(select coalesce(sum(r.quantity),0) from public.inventory_reservations r where r.batch_id=v_batch.id and r.status=''active'')\n   or not k2_private.lot_is_eligible_v1(v_batch) then\n  raise exception ''K2_PACKING_ALLOCATION_INVALID'' using errcode=''23514''; end if;\n update public.inventory_reservations set packed_quantity=packed_quantity+1,updated_at=v_k2_instant where id=v_res.id;\n select coalesce(max(scan_number),0)+1 into v_scan from public.packing_scan_events where order_request_item_id=v_line.id;\n insert into public.packing_scan_events(order_request_id,order_request_item_id,reservation_id,batch_id,sku,scanned_code,scan_number,actor_id, created_at)\n  values(v_order.id,v_line.id,v_res.id,v_batch.id,v_line.sku,trim(p_scanned_code),v_scan,auth.uid(), v_k2_instant);\n select coalesce(sum(packed_quantity),0) into v_total from public.inventory_reservations where order_request_item_id=v_line.id and status=''active'';\n if v_total=v_line.quantity then update public.orders set order_status=''Packed'' where order_request_id=v_order.id and sku=v_line.sku and order_status::text=''Pending''; end if;\n select exists(select 1 from public.order_request_items where order_request_id=v_order.id)\n   and not exists(select 1 from public.order_request_items i where i.order_request_id=v_order.id\n    and i.quantity<>coalesce((select sum(r.packed_quantity) from public.inventory_reservations r where r.order_request_item_id=i.id and r.status=''active''),0)) into v_complete;\n if v_complete then update public.order_requests set delivery_status=''packed'',updated_at=v_k2_instant where id=v_order.id; end if;\n insert into public.order_request_events(order_request_id,from_status,to_status,actor_id,metadata, created_at)\n  values(v_order.id,''confirmed'',''confirmed'',auth.uid(),jsonb_build_object(''event'',''unit_packed'',''sku'',v_line.sku,\n   ''batch_id'',v_batch.id,''reservation_id'',v_res.id,''physical_lot_confirmed'',true,''scan_number'',v_scan), v_k2_instant);\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n return jsonb_build_object(''order_reference'',v_order.public_reference,''sku'',v_line.sku,''product_name'',v_line.product_name,\n  ''packed_quantity'',v_total,''required_quantity'',v_line.quantity,''line_complete'',v_total=v_line.quantity,''order_complete'',v_complete,''batch_id'',v_batch.id);\nend;\n"},{"signature":"public.fulfill_order_request(uuid, text)","before":"073c29130dfc9f82dc4a5cd117b8a350","after":"037c7d2490d2be6efa98cf5d4fe9bb61","metadata":{"proacl":["postgres=X/postgres","authenticated=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"fulfill_order_request","prorows":0,"pronargs":2,"proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"proargmodes":null,"proargnames":["p_order_request_id","p_handover_note"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":0},"body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_res public.inventory_reservations;\n  v_summary record;\n  v_balance public.inventory_balances; v_handover_reservation_ids uuid[];\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() then raise exception ''Staff access required''; end if;\n  if nullif(trim(coalesce(p_handover_note, '''')), '''') is null then raise exception ''Courier or handover note is required''; end if;\n  select * into v_order from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n  if v_order.status = ''fulfilled'' then return v_order; end if;\n  if v_order.status <> ''confirmed'' then raise exception ''Order request is not confirmed''; end if;\n  if v_order.payment_status is distinct from ''verified'' then raise exception ''Payment must be explicitly verified before fulfillment''; end if;\n  if coalesce(v_order.shipping_quote_status,'''') not in (''platform_charged'', ''customer_confirmed'', ''waived'') then\n    raise exception ''Delivery charge or customer confirmation is still pending'';\n  end if;\n\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  -- Lock all affected rows before validating, in the prepared release order.\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN''\n   and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id)\n   order by b.sku for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id\n   order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.id in(\n   select batch_id from public.inventory_reservations where order_request_id=v_order.id and status=''active'')\n   order by b.sku,b.id for update;\n  select array_agg(id) into v_handover_reservation_ids from public.inventory_reservations\n   where order_request_id=v_order.id and status=''active'';\n  if not exists(select 1 from public.order_request_items where order_request_id=v_order.id)\n   or exists(select 1 from public.order_request_items i where i.order_request_id=v_order.id\n    and (i.quantity is null or i.quantity<=0 or i.quantity<>coalesce((select sum(r.quantity)\n      from public.inventory_reservations r where r.order_request_id=v_order.id\n      and r.order_request_item_id=i.id and r.sku=i.sku and r.status=''active''\n      and r.packed_quantity=r.quantity),0)))\n   or exists(select 1 from public.inventory_reservations r\n    left join public.order_request_items i on i.id=r.order_request_item_id and i.order_request_id=v_order.id and i.sku=r.sku\n    left join public.product_batches b on b.id=r.batch_id and b.sku=r.sku\n    left join public.inventory_balances bal on bal.sku=r.sku and bal.location_code=''MANILA_MAIN''\n    where r.id=any(v_handover_reservation_ids) and (i.id is null or b.id is null or bal.sku is null\n     or r.quantity<=0 or r.packed_quantity is distinct from r.quantity\n     or b.inventory_status is distinct from ''available''\n     or b.quantity<b.reserved_quantity or b.reserved_quantity<(select sum(x.quantity) from public.inventory_reservations x where x.batch_id=b.id and x.status=''active'')\n     or bal.on_hand<bal.reserved or bal.reserved<(select sum(x.quantity) from public.inventory_reservations x where x.order_request_id=v_order.id and x.sku=r.sku and x.status=''active'')\n     or not k2_private.lot_is_eligible_v1(b))) then\n   raise exception ''K2_RESERVATION_RECONCILIATION_REQUIRED'' using errcode=''23514'';\n  end if;\n  -- K2_HANDOVER_STOCK_COMMITMENT_V1\n  -- Locked exact allocations must already carry attributable ownership evidence.\n  -- Never backfill a historical sale or deduct ownership for the first time at dispatch.\n  if exists(select 1 from public.inventory_reservations r where r.id=any(v_handover_reservation_ids)\n    and (r.committed_at is null or r.committed_by is null\n      or not coalesce(r.commit_cause in (''confirmation'',''payment_verification''),false))) then\n    raise exception ''K2_RESERVATION_RECONCILIATION_REQUIRED'' using errcode=''23514'';\n  end if;\n  if exists (select 1 from public.inventory_reservations where order_request_id = v_order.id and status = ''active'' and packed_quantity <> quantity) then\n    raise exception ''Every required unit must be scanned before fulfillment'';\n  end if;\n  if exists (\n    select 1 from public.inventory_reservations r join public.product_batches b on b.id = r.batch_id\n    where r.order_request_id = v_order.id and r.status = ''active''\n      and not k2_private.lot_is_eligible_v1(b)\n  ) then raise exception ''A reserved lot is no longer sellable; resolve the inventory exception first''; end if;\n\n  for v_res in select * from public.inventory_reservations where order_request_id = v_order.id and status = ''active'' for update\n  loop\n    update public.product_batches\n    set quantity = quantity - v_res.quantity,\n        reserved_quantity = reserved_quantity - v_res.quantity,\n        inventory_status = case when quantity - v_res.quantity = 0 then ''depleted'' else inventory_status end,\n        updated_at = v_k2_instant\n    where id = v_res.batch_id and quantity >= v_res.quantity and reserved_quantity >= v_res.quantity;\n    if not found then raise exception ''Exact lot quantity mismatch for %'', v_res.sku; end if;\n    update public.inventory_reservations set status = ''fulfilled'', updated_at = v_k2_instant where id = v_res.id;\n  end loop;\n\n  for v_summary in select sku, sum(quantity)::integer quantity\n    from public.inventory_reservations where id = any(v_handover_reservation_ids) group by sku\n  loop\n    update public.inventory_balances\n    set on_hand = on_hand - v_summary.quantity, reserved = reserved - v_summary.quantity, updated_at = v_k2_instant\n    where sku = v_summary.sku and location_code = ''MANILA_MAIN''\n      and on_hand >= v_summary.quantity and reserved >= v_summary.quantity;\n    if not found then raise exception ''Inventory balance mismatch for %'', v_summary.sku; end if;\n    select * into v_balance from public.inventory_balances where sku = v_summary.sku and location_code = ''MANILA_MAIN'';\n    perform set_config(''k2.allow_stock_write'', ''on'', true);\n    update public.products set stock_available = (\n      select coalesce(sum(b.quantity - b.reserved_quantity), 0)::integer from public.product_batches b\n      where b.sku = v_summary.sku and b.inventory_status = ''available''\n        and k2_private.lot_is_eligible_v1(b)\n    ) where sku = v_summary.sku;\n    insert into public.inventory_events (sku, location_code, event_type, quantity, reference_type, reference_id, reason, actor_id, created_at)\n    values (v_summary.sku, ''MANILA_MAIN'', ''fulfilled'', v_summary.quantity, ''order_request'', v_order.id, p_handover_note, auth.uid(), v_k2_instant);\n  end loop;\n\n  update public.orders set order_status = ''Shipped''::order_status_enum where order_request_id = v_order.id;\n  update public.coupon_redemptions set status = ''redeemed'', updated_at = v_k2_instant\n  where order_request_id = v_order.id and status = ''reserved'';\n  update public.order_requests\n  set status = ''fulfilled'', delivery_status = ''handed_to_courier'', fulfilled_at = v_k2_instant, updated_at = v_k2_instant\n  where id = v_order.id returning * into v_order;\n  insert into public.order_request_events (order_request_id, from_status, to_status, reason, actor_id, created_at)\n  values (v_order.id, ''confirmed'', ''fulfilled'', p_handover_note, auth.uid(), v_k2_instant);\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return v_order;\nend;\n"},{"signature":"public.extend_reservation_v1(uuid, integer, text)","before":"c93b14351d3496b487ee75422d3d1d15","after":"4974dea8ed2418f1d7876abc649eebb7","metadata":{"proacl":["postgres=X/postgres","authenticated=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"extend_reservation_v1","prorows":1000,"pronargs":3,"proconfig":["search_path=\"\""],"proretset":true,"prosecdef":true,"proargmodes":["i","i","i","t","t","t"],"proargnames":["p_reservation_id","p_minutes","p_reason","reservation_id","expires_at","extension_count"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":0},"body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_row public.inventory_reservations;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() then\n    raise exception ''STAFF_REQUIRED'' using errcode = ''42501'';\n  end if;\n  -- OWNER-002: no less than 30 minutes, no more than 7 days.\n  if p_minutes is null or p_minutes < 30 or p_minutes > 10080 then\n    raise exception ''RESERVATION_EXTENSION_OUT_OF_BOUNDS'' using errcode = ''22023'';\n  end if;\n  if char_length(btrim(coalesce(p_reason, ''''))) < 10 then\n    raise exception ''RESERVATION_EXTENSION_REASON_REQUIRED'' using errcode = ''22023'';\n  end if;\n\n  perform 1 from public.order_requests where id=(select order_request_id from public.inventory_reservations where id=p_reservation_id) for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku=(select sku from public.inventory_reservations where id=p_reservation_id) order by b.sku for update;\n  perform 1 from public.products p where p.sku=(select sku from public.inventory_reservations where id=p_reservation_id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations where id=p_reservation_id for update;\n  perform 1 from public.product_batches b where b.sku=(select sku from public.inventory_reservations where id=p_reservation_id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  select * into v_row from public.inventory_reservations\n  where id = p_reservation_id for update;\n  if not found then\n    raise exception ''RESERVATION_NOT_FOUND'' using errcode = ''22023'';\n  end if;\n  if v_row.status <> ''active'' then\n    raise exception ''RESERVATION_NOT_ACTIVE'' using errcode = ''22023'';\n  end if;\n  if v_row.expires_at is null then\n    raise exception ''RESERVATION_HAS_NO_DEADLINE'' using errcode = ''22023'';\n  end if;\n  -- K2_EXTEND_COMMITTED_RESERVATION_GUARD_V1: committed reservations are owned stock and never expire.\n  if v_row.committed_at is not null then\n    raise exception ''RESERVATION_ALREADY_COMMITTED'' using errcode = ''22023'';\n  end if;\n  -- Refuse to revive. Staff must create a new reservation instead.\n  if v_row.expires_at <= v_k2_instant then\n    raise exception ''RESERVATION_ALREADY_EXPIRED'' using errcode = ''22023'';\n  end if;\n\n  if not exists(select 1 from public.product_batches b where b.id=v_row.batch_id and b.sku=v_row.sku and k2_private.lot_is_eligible_v1(b)) then\n    raise exception using errcode=''23514'',message=''K2_RESERVATION_RECONCILIATION_REQUIRED'';\n  end if;\n  update public.inventory_reservations\n  set expires_at = v_row.expires_at + make_interval(mins => p_minutes),\n      extension_count = v_row.extension_count + 1,\n      last_extended_at = v_k2_instant,\n      last_extended_by = auth.uid(),\n      last_extension_reason = btrim(p_reason),\n      updated_at = v_k2_instant\n  where id = p_reservation_id\n  returning id, inventory_reservations.expires_at, inventory_reservations.extension_count\n  into reservation_id, expires_at, extension_count;\n\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return next;\nend;\n"},{"signature":"public.release_expired_reservations_v1(integer)","before":"5d36ee8ddf79a6f4524919872c63c8d7","after":"0f52cf814525ab5dad9a70955419c008","metadata":{"proacl":["postgres=X/postgres","authenticated=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"release_expired_reservations_v1","prorows":1000,"pronargs":1,"proconfig":["search_path=\"\""],"proretset":true,"prosecdef":true,"proargmodes":["i","t","t"],"proargnames":["p_limit","released_count","released_ids"],"proisstrict":false,"proparallel":"u","provolatile":"v","proleakproof":false,"pronargdefaults":1},"body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_orders uuid[] := ''{}'';\n  v_ids uuid[] := ''{}'';\n  v_summary record;\n  v_res public.inventory_reservations;\n  v_count integer := 0;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() then raise exception ''STAFF_REQUIRED'' using errcode=''42501''; end if;\n  if p_limit is null or p_limit<1 or p_limit>5000 then raise exception ''RELEASE_LIMIT_INVALID'' using errcode=''22023''; end if;\n  -- The limit bounds complete orders, not arbitrary reservation fragments.\n  -- Lock orders before their inventory so confirmation/cancellation serializes.\n  for v_order in\n    select o.* from public.order_requests o\n    where o.status=''submitted'' and o.payment_status in (''unpaid'',''not_requested'',''awaiting_instructions'',''failed'')\n      and exists(select 1 from public.inventory_reservations r where r.order_request_id=o.id\n        and r.status=''active'' and r.expires_at<=clock_timestamp())\n      and not exists(select 1 from public.inventory_reservations r where r.order_request_id=o.id\n        and r.status=''active'' and (r.packed_quantity>0 or r.expires_at is null or r.committed_at is not null))\n    order by o.id limit p_limit for update of o skip locked\n  loop\n    v_orders := array_append(v_orders,v_order.id);\n  end loop;\n  -- Acquire all affected balances before reservation/batch updates. Common SKU\n  -- order across this batch avoids reverse basket order within the sweep.\n  perform 1 from public.inventory_balances b\n    where b.location_code=''MANILA_MAIN'' and b.sku in (\n      select r.sku from public.inventory_reservations r where r.order_request_id=any(v_orders) and r.status=''active''\n    ) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select r.sku from public.inventory_reservations r where r.order_request_id=any(v_orders) and r.status=''active'') order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=any(v_orders) and r.status=''active''\n    order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select r.sku from public.inventory_reservations r where r.order_request_id=any(v_orders) and r.status=''active'') order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  -- An extension may have committed while the sweep waited for these rows.\n  -- Decide again from the now-locked facts; the earlier selection is not proof.\n  select coalesce(array_agg(o.id),''{}''::uuid[]) into v_orders from public.order_requests o\n    where o.id=any(v_orders) and o.status=''submitted''\n      and o.payment_status in (''unpaid'',''not_requested'',''awaiting_instructions'',''failed'')\n      and exists(select 1 from public.inventory_reservations r where r.order_request_id=o.id\n        and r.status=''active'' and r.expires_at<=v_k2_instant)\n      and not exists(select 1 from public.inventory_reservations r where r.order_request_id=o.id\n        and r.status=''active'' and (r.packed_quantity>0 or r.expires_at is null or r.committed_at is not null));\n  perform 1 from public.product_batches b where b.id in (\n    select batch_id from public.inventory_reservations where order_request_id=any(v_orders) and status=''active''\n  ) order by b.sku,b.id for update;\n\n  for v_summary in select r.order_request_id,r.sku,sum(r.quantity)::integer quantity\n    from public.inventory_reservations r where r.order_request_id=any(v_orders) and r.status=''active''\n    group by r.order_request_id,r.sku order by r.sku,r.order_request_id\n  loop\n    update public.inventory_balances set reserved=reserved-v_summary.quantity,updated_at=v_k2_instant\n      where sku=v_summary.sku and location_code=''MANILA_MAIN'' and reserved>=v_summary.quantity;\n    if not found then raise exception ''K2_RESERVATION_BALANCE_MISMATCH'' using errcode=''23514''; end if;\n    for v_res in select * from public.inventory_reservations\n      where order_request_id=v_summary.order_request_id and sku=v_summary.sku and status=''active''\n      order by batch_id,id\n    loop\n      update public.product_batches set reserved_quantity=reserved_quantity-v_res.quantity,updated_at=v_k2_instant\n        where id=v_res.batch_id and sku=v_res.sku and reserved_quantity>=v_res.quantity;\n      if not found then raise exception ''K2_RESERVATION_LOT_MISMATCH'' using errcode=''23514''; end if;\n      update public.inventory_reservations set status=''released'',released_at=v_k2_instant,\n        release_cause=''expired'',updated_at=v_k2_instant where id=v_res.id;\n      v_ids:=array_append(v_ids,v_res.id); v_count:=v_count+1;\n    end loop;\n    perform set_config(''k2.allow_stock_write'',''on'',true);\n    update public.products set stock_available=(\n      select coalesce(sum(b.quantity-b.reserved_quantity),0)::integer from public.product_batches b\n      where b.sku=v_summary.sku and b.inventory_status=''available''\n        and k2_private.lot_is_eligible_v1(b)\n    ) where sku=v_summary.sku;\n    insert into public.inventory_events(sku,location_code,event_type,quantity,reference_type,reference_id,reason,actor_id, created_at)\n      values(v_summary.sku,''MANILA_MAIN'',''reservation_released'',v_summary.quantity,''order_request'',\n        v_summary.order_request_id,''Expired unpaid purchase hold; released the complete order allocation.'',auth.uid(), v_k2_instant);\n  end loop;\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return query select v_count,v_ids;\nend;\n"}]'::jsonb)
  as x(signature text,before text,after text,metadata jsonb,body text) loop
  select * into b from pg_catalog.pg_proc where oid=to_regprocedure(t.signature);
  d:=pg_catalog.pg_get_functiondef(b.oid);
  if position(b.prosrc in d)=0 then raise exception 'K2_GUEST_OPERATIONS_DEFINITION_INVALID';end if;
  execute replace(d,b.prosrc,t.body);
  select * into a from pg_catalog.pg_proc where oid=b.oid;
  if md5(replace(a.prosrc,chr(13),''))<>t.after
   or (to_jsonb(a)-'prosrc') is distinct from (to_jsonb(b)-'prosrc') then
   raise exception 'K2_GUEST_OPERATIONS_POSTFLIGHT_FAILED: %',t.signature;
  end if;
 end loop;
 execute 'create function k2_private.start_guest_category_lot_context_v1(p_maximum_depth integer,p_nonce uuid)
 returns timestamptz language plpgsql security definer set search_path='''' as $start$
declare v_instant timestamptz;
begin
 if p_maximum_depth is null or p_maximum_depth<1 then
  raise exception using errcode=''22023'',message=''K2_CATEGORY_CONTEXT_INPUT_INVALID'';
 end if;
 if not exists(select 1 from k2_private.guest_request_nonces n
  where n.action=''order'' and n.nonce=p_nonce
   and n.verified_backend_pid=pg_catalog.pg_backend_pid()
   and n.verified_transaction_id=pg_catalog.pg_current_xact_id()
   and n.expires_at>pg_catalog.clock_timestamp()) then
  raise exception using errcode=''42501'',message=''K2_GUEST_CONTEXT_PROOF_REQUIRED'';
 end if;
 -- Verify an existing boundary; never acquire a late policy lock here.
 if not exists(select 1 from pg_catalog.pg_locks l where l.pid=pg_catalog.pg_backend_pid()
  and l.locktype=''advisory'' and l.classid=1261585232::oid and l.objid=1347374169::oid
  and l.objsubid=2 and l.granted and l.mode in (''ShareLock'',''ExclusiveLock'')) then
  raise exception using errcode=''55000'',message=''K2_CATEGORY_CONTEXT_ENTRY_REQUIRED'';
 end if;
 if exists(select 1 from k2_private.category_lot_command_context
  where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then
  raise exception using errcode=''55000'',message=''K2_CATEGORY_CONTEXT_ALREADY_SET'';
 end if;
 v_instant:=pg_catalog.clock_timestamp();
 insert into k2_private.category_lot_command_context
 (backend_pid,transaction_id,actor_id,maximum_depth,evaluation_instant,authority_kind,guest_nonce)
 values(pg_catalog.pg_backend_pid(),pg_catalog.pg_current_xact_id(),auth.uid(),p_maximum_depth,v_instant,''guest'',p_nonce);
 return v_instant;
end $start$;';
 revoke all on function k2_private.start_guest_category_lot_context_v1(integer,uuid)
  from public,anon,authenticated,service_role;
end $guest_operations$;
